<script setup lang="ts">
import { ref, computed, onMounted, watch } from 'vue'
import { useRouter } from 'vue-router'
import { Search, RefreshCw, ClipboardList, ChevronLeft, ChevronRight, ChevronDown, ChevronUp, CircleSlash, Eye, MessageSquare, RotateCcw } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

interface Ticket {
  id: number
  description: string
  category: string
  status: number
  ticket_type: string
  created_at: string
  urgency: string
}

const router = useRouter()
const tickets = ref<Ticket[]>([])
const loading = ref(false)
const currentTab = ref('all')
const showFilters = ref(false)

const statusFilter = ref('')
const categoryFilter = ref('')
const keyword = ref('')

const currentPage = ref(1)
const pageSize = ref(20)
const total = ref(0)

const processingCount = ref(0)
const confirmCount = ref(0)

const selectedIds = ref<number[]>([])

const statusMap: Record<number, { text: string; color: string }> = {
  0: { text: '待回复', color: 'bg-yellow-100 text-yellow-700' },
  1: { text: '客户发送', color: 'bg-blue-100 text-blue-700' },
  2: { text: '客服答复', color: 'bg-orange-100 text-orange-700' },
  3: { text: '结案关闭', color: 'bg-gray-100 text-gray-500' },
}

const categoryMap: Record<string, string> = {
  ecs: 'ECS',
  oss: '文件存储',
  rds: '云数据库MySQL',
  waf: 'WAF',
  vpc: 'VPC',
  ddos: 'DDoS高防防护',
  metal: '裸金属',
  elastic_ip: '弹性IP',
  auto_scale: '负载均衡',
  other: '其他',
  chat: '在线客服',
}

const ticketTypeMap: Record<string, { text: string; color: string }> = {
  standard: { text: '标准工单', color: 'bg-blue-50 text-blue-600' },
  chat: { text: '在线客服', color: 'bg-green-50 text-green-600' },
}

const tabList = computed(() => [
  { key: 'all', label: '全部', count: total.value },
  { key: 'processing', label: '服务中', count: processingCount.value },
  { key: 'confirm', label: '待您确认结果', count: confirmCount.value },
])

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchTickets = async () => {
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }
  loading.value = true
  try {
    const params = new URLSearchParams()
    params.set('page', String(currentPage.value))
    params.set('page_size', String(pageSize.value))
    if (statusFilter.value) params.set('status', statusFilter.value)
    if (categoryFilter.value) params.set('category', categoryFilter.value)
    if (keyword.value) params.set('keyword', keyword.value)
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.list}?${params.toString()}`, {
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      tickets.value = data.data.list || []
      total.value = data.data.total || 0
      processingCount.value = data.data.processing || 0
      confirmCount.value = data.data.confirm || 0
    } else {
      toast.error(data.echo || '查询失败')
    }
  } catch (e) {
    console.error('[fetchTickets]', e)
    toast.error('查询失败')
  } finally {
    loading.value = false
  }
}

const allSelected = computed(() => {
  return tickets.value.length > 0 && tickets.value.every(t => selectedIds.value.includes(t.id))
})

const toggleSelectAll = () => {
  if (allSelected.value) {
    selectedIds.value = []
  } else {
    selectedIds.value = tickets.value.map(t => t.id)
  }
}

const toggleSelect = (id: number) => {
  const index = selectedIds.value.indexOf(id)
  if (index > -1) {
    selectedIds.value.splice(index, 1)
  } else {
    selectedIds.value.push(id)
  }
}

const handleSearch = () => {
  currentPage.value = 1
  fetchTickets()
}

const handleRefresh = () => {
  selectedIds.value = []
  statusFilter.value = ''
  categoryFilter.value = ''
  keyword.value = ''
  currentPage.value = 1
  fetchTickets()
}

// 工单不再提供删除，统一改为「结案关闭」（后端仅提供单条关闭接口，这里逐条调用）
const handleBatchClose = async () => {
  if (selectedIds.value.length === 0) {
    toast.error('请先选择要关闭的工单')
    return
  }
  const count = selectedIds.value.length
  if (!confirm(`确定要关闭选中的 ${count} 个工单吗？关闭后可重新开启。`)) return
  const auth = getAuthHeaders()
  if (!auth) return
  try {
    const results = await Promise.all(
      selectedIds.value.map(async (id) => {
        const form = new FormData()
        form.append('id', String(id))
        const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.close}`, {
          method: 'POST',
          headers: { 'uid': auth.uid, 'token': auth.token },
          body: form,
        })
        const data = await res.json()
        return data.code === 0
      }),
    )
    const closed = results.filter(Boolean).length
    if (closed > 0) {
      toast.success(`已关闭 ${closed} 个工单`)
    }
    if (closed < count) {
      toast.error(`${count - closed} 个工单关闭失败`)
    }
    selectedIds.value = []
    fetchTickets()
  } catch (e) {
    console.error('[handleBatchClose]', e)
    toast.error('关闭失败')
  }
}

const viewTicket = (ticket: Ticket) => {
  router.push({ name: 'console-user-ticket-detail', params: { id: ticket.id } })
}

const replyTicket = (ticket: Ticket) => {
  router.push({ name: 'console-user-ticket-detail', params: { id: ticket.id } })
}

const handleClose = async (ticket: Ticket) => {
  if (!confirm(`确定要结案关闭工单 #${ticket.id} 吗？关闭后可重新开启。`)) return
  const auth = getAuthHeaders()
  if (!auth) return
  try {
    const form = new FormData()
    form.append('id', String(ticket.id))
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.close}`, {
      method: 'POST',
      headers: { 'uid': auth.uid, 'token': auth.token },
      body: form,
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('工单已关闭')
      fetchTickets()
    } else {
      toast.error(data.echo || '关闭失败')
    }
  } catch (e) {
    console.error('[handleClose]', e)
    toast.error('关闭失败')
  }
}

const handleReopen = async (ticket: Ticket) => {
  if (!confirm('确定要重启该工单吗？工单将重新激活为待回复状态。')) return
  const auth = getAuthHeaders()
  if (!auth) return
  try {
    const form = new FormData()
    form.append('id', String(ticket.id))
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.reopen}`, {
      method: 'POST',
      headers: { 'uid': auth.uid, 'token': auth.token },
      body: form,
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('工单已重启')
      fetchTickets()
    } else {
      toast.error(data.echo || '操作失败')
    }
  } catch (e) {
    console.error('[handleReopen]', e)
    toast.error('操作失败')
  }
}

const prevPage = () => {
  if (currentPage.value > 1) {
    currentPage.value--
    fetchTickets()
  }
}

const nextPage = () => {
  const totalPages = Math.ceil(total.value / pageSize.value)
  if (currentPage.value < totalPages) {
    currentPage.value++
    fetchTickets()
  }
}

const goToPage = () => {
  const totalPages = Math.max(1, Math.ceil(total.value / pageSize.value))
  if (currentPage.value < 1) currentPage.value = 1
  if (currentPage.value > totalPages) currentPage.value = totalPages
  fetchTickets()
}

const formatTime = (t: string) => {
  if (!t) return '-'
  return t.replace('T', ' ').substring(0, 19)
}

watch([pageSize], () => {
  currentPage.value = 1
  fetchTickets()
})

watch(currentTab, () => {
  currentPage.value = 1
  if (currentTab.value === 'processing') {
    statusFilter.value = ''
  } else if (currentTab.value === 'confirm') {
    statusFilter.value = '2'
  } else {
    statusFilter.value = ''
  }
  fetchTickets()
})

onMounted(() => {
  fetchTickets()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">我的工单</h1>
      <p class="text-gray-500 mt-1">查看和管理您提交的所有工单</p>
    </div>

    <div class="p-6 space-y-4">
      <div class="bg-white border border-gray-100">
        <div class="border-b border-gray-100 px-4">
          <div class="flex">
            <button
              v-for="tab in tabList"
              :key="tab.key"
              @click="currentTab = tab.key"
              :class="[
                'px-4 py-3 text-sm font-medium transition-colors border-b-2 -mb-px',
                currentTab === tab.key
                  ? 'text-blue-600 border-blue-600'
                  : 'text-gray-500 border-transparent hover:text-gray-700'
              ]"
            >
              {{ tab.label }}（{{ tab.count }}）
            </button>
          </div>
        </div>

        <div class="p-4">
          <div class="flex items-center justify-between flex-wrap gap-4 mb-4">
            <button
              @click="handleBatchClose"
              class="flex items-center gap-2 px-3 py-1.5 text-sm text-gray-700 border border-gray-300 hover:bg-gray-50 transition-colors"
            >
              <CircleSlash class="w-4 h-4" />
              批量关闭
            </button>

            <div class="flex items-center gap-2">
              <select
                v-model="statusFilter"
                class="px-3 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none"
              >
                <option value="">工单状态</option>
                <option value="0">待回复</option>
                <option value="1">客户发送</option>
                <option value="2">客服答复</option>
                <option value="3">结案关闭</option>
              </select>

              <select
                v-model="categoryFilter"
                class="px-3 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none"
              >
                <option value="">问题分类</option>
                <option value="ecs">ECS</option>
                <option value="oss">文件存储</option>
                <option value="rds">云数据库MySQL</option>
                <option value="waf">WAF</option>
                <option value="vpc">VPC</option>
                <option value="ddos">DDoS高防防护</option>
              </select>

              <div class="relative">
                <Search class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                  v-model="keyword"
                  type="text"
                  placeholder="请输入"
                  class="pl-10 pr-4 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none w-40"
                  @keyup.enter="handleSearch"
                />
              </div>

              <button
                @click="showFilters = !showFilters"
                class="flex items-center gap-1 px-3 py-1.5 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 transition-colors"
              >
                {{ showFilters ? '收起' : '展开' }}
                <ChevronDown v-if="!showFilters" class="w-4 h-4" />
                <ChevronUp v-else class="w-4 h-4" />
              </button>

              <button
                @click="handleRefresh"
                class="flex items-center gap-2 px-3 py-1.5 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 transition-colors"
              >
                <RefreshCw class="w-4 h-4" />
              </button>
            </div>
          </div>

          <div class="border border-gray-200">
            <table class="w-full">
              <thead>
                <tr class="border-b border-gray-200 bg-gray-50">
                  <th class="px-4 py-3 w-10">
                    <input
                      type="checkbox"
                      :checked="allSelected"
                      @change="toggleSelectAll"
                      class="w-4 h-4 text-blue-600 rounded"
                    />
                  </th>
                  <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">问题描述</th>
                  <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">类型</th>
                  <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">问题分类</th>
                  <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">工单状态</th>
                  <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">创建时间</th>
                  <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">操作</th>
                </tr>
              </thead>
              <tbody>
                <tr v-if="tickets.length === 0">
                  <td colspan="7" class="px-4 py-12 text-center text-gray-400">
                    <ClipboardList class="w-12 h-12 text-gray-300 mx-auto mb-2" />
                    <p>{{ loading ? '加载中...' : '无数据' }}</p>
                  </td>
                </tr>
                <tr
                  v-for="ticket in tickets"
                  :key="ticket.id"
                  class="border-b border-gray-100 hover:bg-gray-50 transition-colors"
                >
                  <td class="px-4 py-3">
                    <input
                      type="checkbox"
                      :checked="selectedIds.includes(ticket.id)"
                      @change="toggleSelect(ticket.id)"
                      class="w-4 h-4 text-blue-600 rounded"
                    />
                  </td>
                  <td class="px-4 py-3">
                    <div
                      @click="viewTicket(ticket)"
                      class="text-sm text-blue-600 hover:text-blue-700 cursor-pointer truncate max-w-md"
                    >
                      {{ ticket.description }}
                    </div>
                  </td>
                  <td class="px-4 py-3">
                    <span :class="['inline-flex items-center px-2 py-0.5 text-xs font-medium', ticketTypeMap[ticket.ticket_type]?.color || 'bg-gray-50 text-gray-600']">
                      {{ ticketTypeMap[ticket.ticket_type]?.text || '标准工单' }}
                    </span>
                  </td>
                  <td class="px-4 py-3">
                    <span class="text-sm text-gray-600">{{ categoryMap[ticket.category] || ticket.category }}</span>
                  </td>
                  <td class="px-4 py-3">
                    <span :class="['inline-flex items-center gap-1 px-2 py-0.5 text-xs font-medium', statusMap[ticket.status]?.color || 'bg-gray-100 text-gray-500']">
                      <span :class="['w-1.5 h-1.5 rounded-full', ticket.status === 3 ? 'bg-gray-400' : ticket.status === 0 ? 'bg-yellow-500' : ticket.status === 2 ? 'bg-orange-500' : 'bg-blue-500']"></span>
                      {{ statusMap[ticket.status]?.text || '未知' }}
                    </span>
                  </td>
                  <td class="px-4 py-3 text-sm text-gray-500">{{ formatTime(ticket.created_at) }}</td>
                  <td class="px-4 py-3">
                    <div class="flex items-center justify-end gap-2">
                      <button
                        @click="viewTicket(ticket)"
                        class="px-2 py-1 text-xs text-blue-600 hover:bg-blue-50"
                      >
                        <Eye class="w-3.5 h-3.5 inline mr-0.5" />查看
                      </button>
                      <button
                        v-if="ticket.status !== 3"
                        @click="replyTicket(ticket)"
                        class="px-2 py-1 text-xs text-green-600 hover:bg-green-50"
                      >
                        <MessageSquare class="w-3.5 h-3.5 inline mr-0.5" />回复
                      </button>
                      <button
                        v-if="ticket.status !== 3"
                        @click="handleClose(ticket)"
                        class="px-2 py-1 text-xs text-gray-600 hover:bg-gray-100"
                      >
                        <CircleSlash class="w-3.5 h-3.5 inline mr-0.5" />关闭工单
                      </button>
                      <button
                        v-if="ticket.status === 3"
                        @click="handleReopen(ticket)"
                        class="px-2 py-1 text-xs text-emerald-600 hover:bg-emerald-50"
                      >
                        <RotateCcw class="w-3.5 h-3.5 inline mr-0.5" />重启工单
                      </button>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <div class="mt-4 flex items-center justify-between">
            <div class="text-sm text-gray-500">
              共 <span class="font-medium text-gray-700">{{ total }}</span> 条
            </div>
            <div class="flex items-center gap-2">
              <select
                v-model="pageSize"
                class="px-2 py-1 border border-gray-300 text-sm"
              >
                <option :value="10">10条/页</option>
                <option :value="20">20条/页</option>
                <option :value="50">50条/页</option>
              </select>

              <button
                @click="prevPage"
                :disabled="currentPage <= 1"
                class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronLeft class="w-4 h-4" />
              </button>

              <span class="text-sm text-gray-600">
                第 <span class="font-medium">{{ currentPage }}</span> 页
              </span>

              <button
                @click="nextPage"
                :disabled="currentPage >= Math.ceil(total / pageSize)"
                class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                <ChevronRight class="w-4 h-4" />
              </button>

              <span class="text-sm text-gray-500 ml-2">前往</span>
              <input
                v-model.number="currentPage"
                type="number"
                min="1"
                class="w-12 px-2 py-1 border border-gray-300 text-sm text-center"
                @change="goToPage"
              />
              <span class="text-sm text-gray-500">页</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>