<script setup lang="ts">
import { ref, computed, watch, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ChevronLeft, ChevronRight, LayoutDashboard, Server, HardDrive, Cloud, Shield, Users, Settings, Plus, Search, Trash2, ShieldCheck, AlertTriangle, FileText, Cpu, HardDrive as Disk, Zap, Globe, Bell, Target, Eye, UserPlus, Lock, ClipboardList, User, LogIn, ShieldAlert, Layers, HelpCircle, Wallet, ShoppingCart, FileBarChart, Megaphone, Ticket, MessageSquare, UserCog, ChevronDown, CreditCard, Receipt, Wifi, Database, Clock, Package } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'

interface MenuItem {
  key: string
  name: string
  icon: any
  path?: string
  hasChildren?: boolean
  groupKey?: string
  children?: MenuItem[]
}

const route = useRoute()
const router = useRouter()
const collapsed = ref(false)
const logTypes = ref<{ id: number; name: string; code: string }[]>([])
const expandedMenus = ref<Record<string, boolean>>({
  recharge: false,
  promotion: false,
  ticket: false,
  account: false,
})

const typeIconMap: Record<string, any> = {
  user: User,
  system: Shield,
  ak: Settings,
  login: LogIn,
  security: ShieldAlert,
}

const activeSubKey = computed(() => {
  const path = route.path
  const module = currentModule.value
  const menus = currentSubMenus.value
  if (menus && menus.length > 0) {
    // Handle query parameter based modules
    if (module === 'logs' || module === 'ecs' || module === 'network' || module === 'storage') {
        let queryKey = ''
        let defaultKey = ''
        
        if (module === 'logs') {
          queryKey = route.query.log_type_id as string
          defaultKey = 'all'
        } else if (module === 'ecs') {
          queryKey = route.query.tab as string
          defaultKey = 'instances'
        } else if (module === 'network') {
          queryKey = route.query.tab as string
          defaultKey = 'vpc'
        } else if (module === 'storage') {
          queryKey = route.query.tab as string
          defaultKey = 'disk'
        }
      
      if (queryKey) {
        const matched = menus.find(m => m.key === String(queryKey))
        if (matched) return matched.key
      }
      return defaultKey
    }
    
    // Handle user module with nested menus
    if (module === 'user') {
      for (const item of menus) {
        if (item.hasChildren && item.children && item.children.length > 0) {
          const matchedChild = item.children.find((c: any) => c.path && (path === c.path || path.startsWith(c.path + '/')))
          if (matchedChild) return matchedChild.key
        }
      }
      const matched = menus.find(m => m.path && (path === m.path || path.startsWith(m.path + '/')))
      if (matched) return matched.key
      return ''
    }
    
    // Default case for other modules
    const matched = menus.find(m => m.path === path)
    if (matched) return matched.key
    return menus[0].key
  }
  return ''
})

const staticSubMenus: Record<string, MenuItem[]> = {
  dashboard: [
    { key: 'overview', name: '资源概览', icon: LayoutDashboard, path: '/console/dashboard' },
    { key: 'notification', name: '消息中心', icon: Bell, path: '/console/notification' },
  ],
  ecs: [
    { key: 'instances', name: '实例列表', icon: Server, path: '/console/ecs?tab=instances' },
    { key: 'security-group', name: '安全组', icon: ShieldCheck, path: '/console/ecs?tab=security-group' },
    { key: 'snapshots', name: '快照管理', icon: FileText, path: '/console/ecs?tab=snapshots' },
  ],
  network: [
    { key: 'vpc', name: 'VPC', icon: Globe, path: '/console/network?tab=vpc' },
    { key: 'subnet', name: '子网', icon: Server, path: '/console/network?tab=subnet' },
    { key: 'eip', name: '弹性公网IP', icon: Wifi, path: '/console/network?tab=eip' },
    { key: 'sbw', name: '共享带宽', icon: Zap, path: '/console/network?tab=sbw' },
    { key: 'nat', name: 'NAT网关', icon: Shield, path: '/console/network?tab=nat' },
    { key: 'lb', name: '负载均衡', icon: Server, path: '/console/network?tab=lb' },
  ],
  storage: [
    { key: 'disk', name: '云盘', icon: HardDrive, path: '/console/storage?tab=disk' },
    { key: 'snapshot', name: '快照', icon: Database, path: '/console/storage?tab=snapshot' },
    { key: 'snapshot-policy', name: '快照策略', icon: Clock, path: '/console/storage?tab=snapshot-policy' },
    { key: 'fs', name: '文件存储', icon: Server, path: '/console/storage?tab=fs' },
  ],
  resManage: [
    { key: 'res-bag', name: '资源包', icon: Package, path: '/console/res-manage/res-bag' },
  ],
  users: [
    { key: 'list', name: 'AK列表', icon: Users, path: '/console/users' },
    { key: 'logs', name: 'AK日志', icon: ClipboardList, path: '/console/users/logs' },
  ],
  settings: [
    { key: 'profile', name: '个人信息', icon: UserPlus, path: '/console/settings/profile' },
    { key: 'security', name: '安全设置', icon: Shield, path: '/console/settings/security' },
    { key: 'notification', name: '通知设置', icon: Bell, path: '/console/settings/notification' },
    { key: 'verification', name: '实名认证', icon: ShieldCheck, path: '/console/settings/verification' },
    { key: 'help', name: '帮助中心', icon: HelpCircle, path: '/console/help' },
  ],
  user: [
    { key: 'orders', name: '我的订单', icon: ShoppingCart, path: '/console/user/orders' },
    { key: 'billing', name: '账单管理', icon: FileBarChart, path: '/console/user/billing' },
    {
      key: 'recharge-group',
      name: '充值',
      icon: Wallet,
      hasChildren: true,
      groupKey: 'recharge',
      children: [
        { key: 'recharge', name: '充值', icon: Wallet, path: '/console/user/recharge' },
        { key: 'recharge-orders', name: '充值订单', icon: Receipt, path: '/console/user/recharge-orders' },
        { key: 'balance-log', name: '余额流水', icon: CreditCard, path: '/console/user/balance-log' },
      ]
    },
    {
      key: 'promotion-group',
      name: '推广',
      icon: Megaphone,
      hasChildren: true,
      groupKey: 'promotion',
      children: [
        { key: 'promo-list', name: '我的推广', icon: Users, path: '/console/user/promotion/list' },
        { key: 'promo-orders', name: '推广订单', icon: ShoppingCart, path: '/console/user/promotion/orders' },
        { key: 'promo-vm', name: '推广云主机', icon: Server, path: '/console/user/promotion/vm' },
        { key: 'promo-link', name: '推广链接', icon: Megaphone, path: '/console/user/promotion/link' },
      ]
    },
    {
      key: 'ticket-group',
      name: '工单管理',
      icon: Ticket,
      hasChildren: true,
      groupKey: 'ticket',
      children: [
        { key: 'ticket-submit', name: '提交工单', icon: FileText, path: '/console/user/ticket/submit' },
        { key: 'ticket-list', name: '我的工单', icon: ClipboardList, path: '/console/user/ticket/list' },
      ]
    },
    { key: 'chat', name: '在线客服', icon: MessageSquare, path: '/console/user/chat' },
    { key: 'coupon', name: '优惠券', icon: Ticket, path: '/console/user/coupon' },
  ],
}

const currentSubMenus = computed((): MenuItem[] => {
  if (currentModule.value === 'logs') {
    const logMenu: MenuItem[] = [
      { key: 'all', name: '综合', icon: Layers, path: '/console/logs' },
    ]
    logTypes.value.forEach(type => {
      logMenu.push({
        key: String(type.id),
        name: type.name,
        icon: typeIconMap[type.code] || FileText,
        path: `/console/logs?log_type_id=${type.id}`,
      })
    })
    return logMenu
  }
  return staticSubMenus[currentModule.value] || []
})

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchLogTypes = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.actionLog.type}`, {
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0) {
      logTypes.value = data.data || []
    }
  } catch (e) {
    console.error('[fetchLogTypes]', e)
  }
}

const currentModule = computed(() => {
  const path = route.path
  if (path.startsWith('/console/dashboard')) return 'dashboard'
  if (path.startsWith('/console/notification')) return 'dashboard'
  if (path.startsWith('/console/ecs')) return 'ecs'
  if (path.startsWith('/console/network')) return 'network'
  if (path.startsWith('/console/storage')) return 'storage'
  if (path.startsWith('/console/res-manage')) return 'resManage'
  if (path.startsWith('/console/users')) return 'users'
  if (path.startsWith('/console/logs')) return 'logs'
  if (path.startsWith('/console/settings')) return 'settings'
  if (path.startsWith('/console/help')) return 'settings'
  if (path.startsWith('/console/user')) return 'user'
  return 'dashboard'
})

const moduleTitle: Record<string, string> = {
  dashboard: '控制台',
  ecs: '云服务器',
  network: '网络',
  storage: '存储',
  resManage: '资源管理',
  users: 'AK管理',
  settings: '账号中心',
  logs: '操作日志',
  user: '用户中心',
}

watch(currentModule, () => {
})

watch(() => route.path, (newPath) => {
  if (currentModule.value === 'user') {
    const menus = staticSubMenus.user
    for (const item of menus) {
      if (item.hasChildren && item.children && item.children.length > 0 && item.groupKey) {
        const matchedChild = item.children.find((c: any) => c.path && (newPath === c.path || newPath.startsWith(c.path + '/')))
        if (matchedChild) {
          expandedMenus.value[item.groupKey] = true
        }
      }
    }
  }
}, { immediate: true })

onMounted(() => {
  fetchLogTypes()
})

const handleSubMenuClick = (item: MenuItem) => {
  if (item.path) {
    if (item.path.includes('?')) {
      const [path, queryString] = item.path.split('?')
      const params = new URLSearchParams(queryString)
      const query: Record<string, string> = {}
      params.forEach((value, key) => { query[key] = value })
      router.push({ path, query })
    } else {
      router.push(item.path)
    }
  }
}

const toggleSidebar = () => {
  collapsed.value = !collapsed.value
}

const toggleExpand = (groupKey: string) => {
  expandedMenus.value[groupKey] = !expandedMenus.value[groupKey]
}

const isChildActive = (children: MenuItem[]) => {
  const path = route.path
  return children.some(child => child.path && (path === child.path || path.startsWith(child.path + '/')))
}

defineExpose({
  collapsed,
  toggleSidebar
})
</script>

<template>
  <aside
    :class="[
      'h-full bg-[#202020] text-white flex flex-col transition-all duration-300 flex-shrink-0',
      collapsed ? 'w-16' : 'w-[199px]'
    ]"
  >
    <div class="px-5 pt-4 pb-3 border-b border-gray-800 flex-shrink-0">
      <span v-if="!collapsed" class="text-lg font-bold text-white">{{ moduleTitle[currentModule] }}</span>
    </div>

    <nav class="flex-1 py-4 overflow-y-auto">
      <ul class="space-y-1 px-2">
        <template v-if="currentModule === 'user'">
          <li v-for="item in currentSubMenus" :key="item.key">
            <template v-if="item.hasChildren && item.children && item.children.length > 0">
              <button
                @click="toggleExpand(item.groupKey)"
                :class="[
                  'w-full flex items-center justify-between gap-3 px-3 py-2.5 transition-all duration-200',
                  isChildActive(item.children)
                    ? 'text-white'
                    : 'text-gray-300 hover:bg-gray-800 hover:text-white'
                ]"
              >
                <div class="flex items-center gap-3">
                  <component :is="item.icon" class="w-5 h-5 flex-shrink-0" />
                  <span v-if="!collapsed" class="text-sm font-medium whitespace-nowrap">{{ item.name }}</span>
                </div>
                <ChevronDown
                  v-if="!collapsed"
                  :class="[
                    'w-4 h-4 flex-shrink-0 transition-transform duration-200',
                    expandedMenus[item.groupKey] ? 'rotate-180' : ''
                  ]"
                />
              </button>
              <Transition name="submenu">
                <ul v-if="expandedMenus[item.groupKey] && !collapsed" class="mt-1 space-y-1 pl-6">
                  <li v-for="child in item.children" :key="child.key">
                    <button
                      @click="handleSubMenuClick(child)"
                      :class="[
                        'w-full flex items-center gap-3 px-3 py-2 transition-all duration-200 text-sm',
                        activeSubKey === child.key
                          ? 'bg-flame-500 text-white shadow-lg shadow-flame-500/25'
                          : 'text-gray-400 hover:bg-gray-800 hover:text-white'
                      ]"
                    >
                      <span class="w-1.5 h-1.5 rounded-full flex-shrink-0" :class="activeSubKey === child.key ? 'bg-white' : 'bg-gray-500'"></span>
                      <span class="whitespace-nowrap">{{ child.name }}</span>
                    </button>
                  </li>
                </ul>
              </Transition>
            </template>
            <template v-else-if="item.hasChildren">
              <button
                @click="toggleExpand(item.groupKey)"
                :class="[
                  'w-full flex items-center justify-between gap-3 px-3 py-2.5 transition-all duration-200',
                  activeSubKey === item.key
                    ? 'bg-flame-500 text-white shadow-lg shadow-flame-500/25'
                    : 'text-gray-300 hover:bg-gray-800 hover:text-white'
                ]"
              >
                <div class="flex items-center gap-3">
                  <component :is="item.icon" class="w-5 h-5 flex-shrink-0" />
                  <span v-if="!collapsed" class="text-sm font-medium whitespace-nowrap">{{ item.name }}</span>
                </div>
                <ChevronDown
                  v-if="!collapsed"
                  :class="[
                    'w-4 h-4 flex-shrink-0 transition-transform duration-200',
                    expandedMenus[item.groupKey] ? 'rotate-180' : ''
                  ]"
                />
              </button>
            </template>
            <template v-else>
              <button
                @click="handleSubMenuClick(item)"
                :class="[
                  'w-full flex items-center gap-3 px-3 py-2.5 transition-all duration-200',
                  activeSubKey === item.key
                    ? 'bg-flame-500 text-white shadow-lg shadow-flame-500/25'
                    : 'text-gray-300 hover:bg-gray-800 hover:text-white'
                ]"
              >
                <component :is="item.icon" class="w-5 h-5 flex-shrink-0" />
                <span v-if="!collapsed" class="text-sm font-medium whitespace-nowrap">{{ item.name }}</span>
              </button>
            </template>
          </li>
        </template>
        <template v-else>
          <li v-for="item in currentSubMenus" :key="item.key">
            <button
              @click="handleSubMenuClick(item)"
              :class="[
                'w-full flex items-center gap-3 px-3 py-2.5 transition-all duration-200',
                activeSubKey === item.key
                  ? 'bg-flame-500 text-white shadow-lg shadow-flame-500/25'
                  : 'text-gray-300 hover:bg-gray-800 hover:text-white'
              ]"
            >
              <component :is="item.icon" class="w-5 h-5 flex-shrink-0" />
              <span v-if="!collapsed" class="text-sm font-medium whitespace-nowrap">{{ item.name }}</span>
            </button>
          </li>
        </template>
      </ul>
    </nav>
  </aside>
</template>

<style scoped>
.submenu-enter-active,
.submenu-leave-active {
  overflow: hidden;
  transition: all 0.2s ease;
}

.submenu-enter-from,
.submenu-leave-to {
  opacity: 0;
  max-height: 0;
}

.submenu-enter-to,
.submenu-leave-from {
  opacity: 1;
  max-height: 200px;
}
</style>