<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { Search, RefreshCw, ChevronDown, ChevronUp, ChevronLeft, ChevronRight, ShoppingCart } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'

interface PromoOrder {
  id: number
  customer: string
  order_no: string
  product_name: string
  amount: string
  quantity: number
  duration: string
  time: string
  pay_type: string
}

const orders = ref<PromoOrder[]>([])
const loading = ref(false)
const showFilters = ref(false)
const productType = ref('ecs')
const searchField = ref('uid')
const searchKeyword = ref('')

const currentPage = ref(1)
const pageSize = ref(20)
const total = ref(0)

const payTypeMap: Record<string, string> = {
  balance: '余额支付',
  alipay: '支付宝',
  wechat: '微信支付',
  bank_transfer: '银行转账',
}

const productOptions = [
  { value: 'ecs', label: 'ECS' },
  { value: 'rds', label: 'RDS' },
  { value: 'oss', label: 'OSS' },
  { value: 'cdn', label: 'CDN' },
  { value: 'slb', label: 'SLB' },
]

const searchFields = [
  { value: 'uid', label: '用户UID' },
  { value: 'order_no', label: '订单编号' },
  { value: 'product', label: '产品名称' },
]

const mockOrders: PromoOrder[] = [
  {
    id: 1, customer: '用户A (订单量: 3)', order_no: 'DD2024072400001', product_name: '云服务器ECS',
    amount: '999.00', quantity: 1, duration: '1个月', time: '2024-07-24 10:30:00', pay_type: 'alipay',
  },
  {
    id: 2, customer: '用户B (订单量: 2)', order_no: 'DD2024072300002', product_name: '云数据库RDS',
    amount: '1,200.00', quantity: 1, duration: '1个月', time: '2024-07-23 15:20:00', pay_type: 'balance',
  },
  {
    id: 3, customer: '用户A (订单量: 3)', order_no: 'DD2024072200003', product_name: '云服务器ECS',
    amount: '599.00', quantity: 1, duration: '1个月', time: '2024-07-22 09:10:00', pay_type: 'wechat',
  },
  {
    id: 4, customer: '用户C (订单量: 1)', order_no: 'DD2024072100004', product_name: 'CDN加速',
    amount: '300.00', quantity: 1, duration: '1个月', time: '2024-07-21 14:45:00', pay_type: 'alipay',
  },
  {
    id: 5, customer: '用户A (订单量: 3)', order_no: 'DD2024072000005', product_name: '负载均衡',
    amount: '299.00', quantity: 2, duration: '1个月', time: '2024-07-20 11:00:00', pay_type: 'balance',
  },
]

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchOrders = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    orders.value = mockOrders
    total.value = mockOrders.length
  } catch (e) {
    console.error('[fetchOrders] 异常', e)
  } finally {
    loading.value = false
  }
}

const handleSearch = () => {
  currentPage.value = 1
  fetchOrders()
}

const handleRefresh = () => {
  fetchOrders()
}

const prevPage = () => {
  if (currentPage.value > 1) {
    currentPage.value--
    fetchOrders()
  }
}

const nextPage = () => {
  const totalPages = Math.ceil(total.value / pageSize.value)
  if (currentPage.value < totalPages) {
    currentPage.value++
    fetchOrders()
  }
}

onMounted(() => {
  fetchOrders()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">推广订单</h1>
      <p class="text-gray-500 mt-1">查看推广产生的所有订单</p>
    </div>

    <div class="p-6">
      <div class="bg-white border border-gray-100">
        <div class="p-4 border-b border-gray-100">
          <div class="flex items-center gap-2 flex-wrap">
            <div class="relative">
              <select
                v-model="productType"
                class="pl-3 pr-8 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none appearance-none cursor-pointer min-w-[100px]"
              >
                <option v-for="p in productOptions" :key="p.value" :value="p.value">{{ p.label }}</option>
              </select>
              <svg class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="6 9 12 15 18 9"></polyline>
              </svg>
            </div>

            <div class="relative">
              <select
                v-model="searchField"
                class="pl-3 pr-8 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none appearance-none cursor-pointer min-w-[120px]"
              >
                <option v-for="f in searchFields" :key="f.value" :value="f.value">{{ f.label }}</option>
              </select>
              <svg class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="6 9 12 15 18 9"></polyline>
              </svg>
            </div>

            <div class="relative">
              <input
                v-model="searchKeyword"
                type="text"
                placeholder="请输入"
                class="pl-3 pr-10 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none w-48"
                @keyup.enter="handleSearch"
              />
              <button
                @click="handleSearch"
                class="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-500"
              >
                <Search class="w-4 h-4" />
              </button>
            </div>

            <button
              @click="showFilters = !showFilters"
              class="flex items-center gap-1 px-3 py-1.5 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 transition-colors"
            >
              {{ showFilters ? '收起' : '展开' }}
              <ChevronDown v-if="!showFilters" class="w-4 h-4" />
              <ChevronUp v-else class="w-4 h-4" />
            </button>

            <button
              @click="handleRefresh"
              class="flex items-center gap-2 px-3 py-1.5 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 transition-colors"
            >
              <RefreshCw class="w-4 h-4" />
            </button>
          </div>

          <div v-if="showFilters" class="mt-4 pt-4 border-t border-gray-100 grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label class="block text-sm text-gray-600 mb-1">支付方式</label>
              <select class="w-full px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">
                <option value="">全部方式</option>
                <option value="balance">余额支付</option>
                <option value="alipay">支付宝</option>
                <option value="wechat">微信支付</option>
              </select>
            </div>
            <div>
              <label class="block text-sm text-gray-600 mb-1">订单时间</label>
              <div class="flex items-center gap-2">
                <input type="date" class="flex-1 px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none" />
                <span class="text-gray-400">至</span>
                <input type="date" class="flex-1 px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none" />
              </div>
            </div>
          </div>
        </div>

        <div class="overflow-x-auto">
          <table class="w-full min-w-max">
            <thead>
              <tr class="border-b border-gray-200 bg-gray-50">
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">客户</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">订单编号</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">产品名称</th>
                <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 whitespace-nowrap">金额</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">数量</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">时长</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">时间</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">支付类型</th>
              </tr>
            </thead>
            <tbody>
              <tr v-if="loading" class="border-b border-gray-100">
                <td colspan="8" class="px-4 py-12 text-center text-gray-400">
                  <RefreshCw class="w-6 h-6 animate-spin mx-auto mb-2" />
                  加载中...
                </td>
              </tr>
              <tr v-else-if="orders.length === 0" class="border-b border-gray-100">
                <td colspan="8" class="px-4 py-12 text-center text-gray-400">
                  <ShoppingCart class="w-12 h-12 text-gray-300 mx-auto mb-2" />
                  <p>无数据</p>
                </td>
              </tr>
              <tr
                v-for="order in orders"
                :key="order.id"
                class="border-b border-gray-100 hover:bg-gray-50 transition-colors"
              >
                <td class="px-4 py-3 text-sm text-gray-700 whitespace-nowrap">{{ order.customer }}</td>
                <td class="px-4 py-3 text-sm text-blue-600 cursor-pointer hover:text-blue-700 whitespace-nowrap">{{ order.order_no }}</td>
                <td class="px-4 py-3 text-sm text-gray-700 whitespace-nowrap">{{ order.product_name }}</td>
                <td class="px-4 py-3 text-sm font-medium text-red-600 text-right whitespace-nowrap">¥{{ order.amount }}</td>
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">{{ order.quantity }}</td>
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">{{ order.duration }}</td>
                <td class="px-4 py-3 text-sm text-gray-500 whitespace-nowrap">{{ order.time }}</td>
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">{{ payTypeMap[order.pay_type] || order.pay_type }}</td>
              </tr>
            </tbody>
          </table>
        </div>

        <div class="px-4 py-4 border-t border-gray-100 flex items-center justify-between">
          <div class="text-sm text-gray-500">
            共 <span class="font-medium text-gray-700">{{ total }}</span> 条
          </div>
          <div class="flex items-center gap-2">
            <select
              v-model="pageSize"
              class="px-2 py-1 border border-gray-300 text-sm"
            >
              <option :value="10">10条/页</option>
              <option :value="20">20条/页</option>
              <option :value="50">50条/页</option>
              <option :value="100">100条/页</option>
            </select>

            <button
              @click="prevPage"
              :disabled="currentPage <= 1"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft class="w-4 h-4" />
            </button>

            <span class="text-sm text-gray-600">
              第 <span class="font-medium">{{ currentPage }}</span> 页
            </span>

            <button
              @click="nextPage"
              :disabled="currentPage >= Math.ceil(total / pageSize)"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight class="w-4 h-4" />
            </button>

            <span class="text-sm text-gray-500 ml-2">前往</span>
            <input
              v-model.number="currentPage"
              type="number"
              min="1"
              class="w-12 px-2 py-1 border border-gray-300 text-sm text-center"
            />
            <span class="text-sm text-gray-500">页</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
