const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchBills = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    bills.value = mockBills
    total.value = mockBills.length
  } catch (e) {
    console.error('[fetchBills] 异常', e)
  } finally {
    loading.value = false
  }
}

const handleSearch = () => {
  currentPage.value = 1
  fetchBills()
}

const handleRefresh = () => {
  fetchBills()
}

const viewDetail = (bill: Bill) => {
  console.log('查看账单详情', bill)
}

const downloadBill = (bill: Bill) => {
  console.log('下载账单', bill)
}

const prevPage = () => {
  if (currentPage.value > 1) {
    currentPage.value--
    fetchBills()
  }
}

const nextPage = () => {
  const totalPages = Math.ceil(total.value / pageSize.value)
  if (currentPage.value < totalPages) {
    currentPage.value++
    fetchBills()
  }
}

onMounted(() => {
  fetchBills()
})
</script>

