<script setup lang="ts">
import { ref, computed } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowLeft, Plus, X, Minus, ChevronDown, Check, Server, HardDrive, Shield, Settings, CreditCard } from 'lucide-vue-next'

const router = useRouter()

// 步骤配置
const steps = [
  { key: 'basic', name: '基础配置', num: 1 },
  { key: 'network', name: '网络配置', num: 2 },
  { key: 'advanced', name: '高级配置', num: 3 },
  { key: 'confirm', name: '确认配置', num: 4 },
]
const currentStep = ref('basic')

// 可用区
const regions = [
  { value: 'cn-hangzhou', label: '华东1(杭州)' },
  { value: 'cn-beijing', label: '华北2(北京)' },
  { value: 'cn-guangzhou', label: '华南1(广州)' },
]
const selectedRegion = ref('cn-hangzhou')
const zones = ['一区', '二区']
const selectedZone = ref('一区')

// 规格
const cpuOptions = ['1核', '2核', '4核', '8核', '16核', '32核']
const selectedCpu = ref('1核')
const memoryOptions = ['1Gb', '2Gb', '4Gb', '8Gb', '16Gb', '32Gb', '64Gb']
const selectedMemory = ref('1Gb')

// 镜像
const imageTypes = ['系统镜像', '自定义镜像']
const selectedImageType = ref('系统镜像')
const imageOsOptions = ['CentOS', 'Ubuntu', 'Windows Server', 'Debian', 'RedHat']
const selectedImageOs = ref('')
const imageVersionOptions: Record<string, string[]> = {
  'CentOS': ['7.9 64位', '8.0 64位', 'Stream 9 64位'],
  'Ubuntu': ['18.04 LTS', '20.04 LTS', '22.04 LTS'],
  'Windows Server': ['2019 数据中心版', '2022 数据中心版'],
  'Debian': ['10 64位', '11 64位', '12 64位'],
  'RedHat': ['7.9 64位', '8.0 64位'],
}
const selectedImageVersion = ref('')

// 系统盘
const systemDiskSize = ref(40)
const systemDiskType = ref('高效云盘')

// 数据盘
interface DataDisk {
  id: number
  size: number
  type: string
}
const dataDisks = ref<DataDisk[]>([])
const maxDataDisks = 5
const diskTypes = ['性能型', '容量型', 'SSD云盘']

const addDataDisk = () => {
  if (dataDisks.value.length < maxDataDisks) {
    dataDisks.value.push({
      id: Date.now(),
      size: 20,
      type: '性能型'
    })
  }
}

const removeDataDisk = (id: number) => {
  dataDisks.value = dataDisks.value.filter(d => d.id !== id)
}

const remainingDataDisks = computed(() => maxDataDisks - dataDisks.value.length)

// 私网
const privateNetworks = [
  { value: 'vpc-001', label: '默认私有网络 192.168.0.0/16' },
  { value: 'vpc-002', label: '生产环境VPC 10.0.0.0/8' },
]
const selectedVpc = ref('')

// 线路
const lineTypes = ['电信', 'BGP']
const selectedLine = ref('电信')

// 带宽
const bandwidth = ref(1)
const minBandwidth = 1
const maxBandwidth = 600

const decreaseBandwidth = () => {
  if (bandwidth.value > minBandwidth) {
    bandwidth.value--
  }
}

const increaseBandwidth = () => {
  if (bandwidth.value < maxBandwidth) {
    bandwidth.value++
  }
}

// 公网IP
const hasPublicIp = ref(true)

// 密码设置
const passwordModes = ['设置密码', '暂不设置']
const passwordMode = ref('暂不设置')
const rootPassword = ref('')
const confirmPassword = ref('')

// 备注
const remark = ref('')

// 购买数量
const purchaseCount = ref(1)
const minCount = 1
const maxCount = 100

const decreaseCount = () => {
  if (purchaseCount.value > minCount) {
    purchaseCount.value--
  }
}

const increaseCount = () => {
  if (purchaseCount.value < maxCount) {
    purchaseCount.value++
  }
}

// 购买周期
const purchasePeriods = [
  { value: 1, label: '1个月', discount: '' },
  { value: 2, label: '2个月', discount: '' },
  { value: 3, label: '3个月', discount: '' },
  { value: 6, label: '6个月', discount: '惠' },
  { value: 12, label: '1年', discount: '惠' },
  { value: 24, label: '2年', discount: '惠' },
  { value: 36, label: '3年', discount: '惠' },
]
const selectedPeriod = ref(1)

// 价格计算
const totalPrice = computed(() => {
  let basePrice = 50
  
  const cpuIndex = cpuOptions.indexOf(selectedCpu.value)
  basePrice += cpuIndex * 30
  
  const memIndex = memoryOptions.indexOf(selectedMemory.value)
  basePrice += memIndex * 25
  
  dataDisks.value.forEach(disk => {
    basePrice += disk.size * 0.6
    if (disk.type === 'SSD云盘') {
      basePrice += disk.size * 0.4
    }
  })
  
  basePrice += bandwidth.value * 5
  
  let periodMultiplier = selectedPeriod.value
  if (selectedPeriod.value >= 6) {
    periodMultiplier *= 0.85
  }
  if (selectedPeriod.value >= 12) {
    periodMultiplier *= 0.8
  }
  
  return (basePrice * purchaseCount.value * periodMultiplier).toFixed(2)
})

// 配置摘要
const configSummary = computed(() => {
  const region = regions.find(r => r.value === selectedRegion.value)?.label || '-'
  const image = selectedImageOs.value && selectedImageVersion.value 
    ? `${selectedImageOs.value} ${selectedImageVersion.value}` 
    : '-'
  
  return {
    region,
    zone: selectedZone.value,
    spec: `${selectedCpu.value}${selectedMemory.value}`,
    image,
    systemDisk: `${systemDiskSize.value}Gb`,
    dataDisks: dataDisks.value.map(d => `${d.type}-${d.size}G`).join(', ') || '-',
    line: selectedLine.value,
    bandwidth: `${bandwidth.value}M`,
    account: passwordMode.value === '设置密码' ? 'root' : '-',
  }
})

// 返回实例列表
const goBack = () => {
  router.push('/console/ecs')
}

import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const loading = ref(false)

// 确认订单
const confirmOrder = async () => {
  // 验证必填项
  if (!selectedImageOs.value || !selectedImageVersion.value) {
    toast.error('请选择镜像操作系统和版本')
    return
  }
  if (!selectedVpc.value) {
    toast.error('请选择私网VPC')
    return
  }
  if (passwordMode.value === '设置密码' && (!rootPassword.value || rootPassword.value !== confirmPassword.value)) {
    toast.error('请输入密码并确认')
    return
  }

  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }

  loading.value = true

  try {
    const orderData = {
      region: selectedRegion.value,
      zone: selectedZone.value,
      cpu: selectedCpu.value,
      memory: selectedMemory.value,
      image_os: selectedImageOs.value,
      image_version: selectedImageVersion.value,
      system_disk_size: systemDiskSize.value,
      system_disk_type: systemDiskType.value,
      data_disks: JSON.stringify(dataDisks.value),
      vpc_id: selectedVpc.value,
      line_type: selectedLine.value,
      bandwidth: bandwidth.value,
      has_public_ip: hasPublicIp.value ? 1 : 0,
      password_mode: passwordMode.value,
      root_password: rootPassword.value,
      purchase_count: purchaseCount.value,
      purchase_period: selectedPeriod.value,
      remark: remark.value,
      total_price: totalPrice.value,
    }

    const body = new URLSearchParams()
    for (const [key, value] of Object.entries(orderData)) {
      body.set(key, String(value))
    }

    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ecs.order.create}`, {
      method: 'POST',
      headers: {
        'uid': auth.uid,
        'token': auth.token,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: body.toString(),
    })

    const data = await res.json()
    if (data.code === 0) {
      toast.success('订单创建成功')
      router.push(`/console/ecs/pay?id=${data.data.id}`)
    } else {
      toast.error(data.echo || '订单创建失败')
    }
  } catch (e) {
    console.error('[confirmOrder] 异常', e)
    toast.error('订单创建失败')
  } finally {
    loading.value = false
  }
}

// 步骤切换
const goToStep = (step: string) => {
  currentStep.value = step
}
</script>

