  <div class="p-6 h-full overflow-y-auto">
    <!-- 顶部标题栏 -->
    <div class="flex items-center gap-4 mb-6">
      <button 
        @click="goBack"
        class="flex items-center gap-1 text-gray-500 hover:text-gray-700 transition-colors"
      >
