            <Server class="w-5 h-5 text-flame-500" />
            <span class="font-medium text-gray-900">基础配置</span>
          </div>
          
          <div class="p-6 space-y-6">
            <!-- 可用区 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0">可用区</label>
              <div class="flex-1">
                <div class="flex items-center gap-3 mb-3">
                  <select 
                    v-model="selectedRegion"
