                  >
                    <option v-for="region in regions" :key="region.value" :value="region.value">
                      {{ region.label }}
                    </option>
                  </select>
                </div>
                <div class="flex items-center gap-4">
                  <label 
                    v-for="zone in zones" 
                    :key="zone"
                    :class="[
                      'flex items-center gap-2 cursor-pointer px-3 py-1.5 border text-sm',
                      selectedZone === zone 
                        ? 'border-flame-500 text-flame-500 bg-flame-50' 
                        : 'border-gray-300 text-gray-700 hover:border-gray-400'
                    ]"
                  >
                    <input 
                      type="radio" 
                      :value="zone" 
                      v-model="selectedZone"
                      class="hidden"
                    />
                    {{ zone }}
                  </label>
                </div>
              </div>
            </div>

            <!-- 规格 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0">规格</label>
              <div class="flex-1 flex items-center gap-3">
                <div class="relative">
                  <select 
                    v-model="selectedCpu"
                    class="px-3 py-2 border border-gray-300 text-sm focus:outline-none focus:ring-2 focus:ring-flame-500/20 focus:border-flame-500 pr-8 appearance-none cursor-pointer min-w-[100px]"
                  >
                    <option v-for="cpu in cpuOptions" :key="cpu" :value="cpu">
                      {{ cpu }}
                    </option>
                  </select>
                  <ChevronDown class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                </div>
                <div class="relative">
                  <select 
                    v-model="selectedMemory"
                    class="px-3 py-2 border border-gray-300 text-sm focus:outline-none focus:ring-2 focus:ring-flame-500/20 focus:border-flame-500 pr-8 appearance-none cursor-pointer min-w-[100px]"
                  >
                    <option v-for="mem in memoryOptions" :key="mem" :value="mem">
                      {{ mem }}
                    </option>
                  </select>
                  <ChevronDown class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                </div>
              </div>
            </div>

            <!-- 镜像 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0">镜像</label>
              <div class="flex-1">
                <div class="flex items-center gap-4 mb-3">
                  <label 
                    v-for="type in imageTypes" 
                    :key="type"
                    :class="[
                      'flex items-center gap-2 cursor-pointer px-3 py-1.5 border text-sm',
                      selectedImageType === type 
                        ? 'border-flame-500 text-flame-500 bg-flame-50' 
                        : 'border-gray-300 text-gray-700 hover:border-gray-400'
                    ]"
                  >
                    <input 
                      type="radio" 
                      :value="type" 
                      v-model="selectedImageType"
                      class="hidden"
                    />
                    {{ type }}
                  </label>
                </div>
                <div class="flex items-center gap-3">
                  <div class="relative">
                    <select 
                      v-model="selectedImageOs"
                      class="px-3 py-2 border border-gray-300 text-sm focus:outline-none focus:ring-2 focus:ring-flame-500/20 focus:border-flame-500 pr-8 appearance-none cursor-pointer min-w-[150px]"
                    >
                      <option value="" disabled>请选择</option>
                      <option v-for="os in imageOsOptions" :key="os" :value="os">
                        {{ os }}
                      </option>
                    </select>
                    <ChevronDown class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                  </div>
                  <div class="relative">
                    <select 
                      v-model="selectedImageVersion"
                      :disabled="!selectedImageOs"
                      class="px-3 py-2 border border-gray-300 text-sm focus:outline-none focus:ring-2 focus:ring-flame-500/20 focus:border-flame-500 pr-8 appearance-none cursor-pointer min-w-[200px] disabled:bg-gray-50 disabled:text-gray-400"
                    >
                      <option value="" disabled>请选择</option>
                      <option v-for="ver in imageVersionOptions[selectedImageOs] || []" :key="ver" :value="ver">
                        {{ ver }}
                      </option>
                    </select>
                    <ChevronDown class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                  </div>
                </div>
              </div>
            </div>

            <!-- 系统盘 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0">系统盘</label>
              <div class="flex-1">
                <span class="text-sm text-gray-700">免费赠送</span>
              </div>
            </div>

            <!-- 数据盘 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0">数据盘</label>
              <div class="flex-1">
                <button 
                  @click="addDataDisk"
                  :disabled="dataDisks.length >= maxDataDisks"
                  :class="[
                    'flex items-center gap-1 px-3 py-1.5 text-sm font-medium transition-colors',
                    dataDisks.length >= maxDataDisks
                      ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                      : 'bg-flame-500 text-white hover:bg-flame-600'
                  ]"
                >
                  <Plus class="w-4 h-4" />
                  增加数据盘
                </button>
                <p class="text-xs text-gray-400 mt-2">
                  您还可以选购 {{ remainingDataDisks }} 块数据盘
                </p>

                <!-- 数据盘列表 -->
                <div class="mt-4 space-y-3">
                  <div 
                    v-for="disk in dataDisks" 
                    :key="disk.id"
                    class="flex items-center gap-3 p-3 bg-gray-50 border border-gray-100"
                  >
                    <button 
                      @click="removeDataDisk(disk.id)"
                      class="p-1 text-gray-400 hover:text-red-500 transition-colors"
                    >
                      <X class="w-4 h-4" />
                    </button>
                    <div class="flex items-center gap-1">
                      <button 
                        @click="disk.size = Math.max(10, disk.size - 10)"
                        class="w-7 h-7 flex items-center justify-center border border-gray-300 text-gray-600 hover:bg-gray-100 transition-colors"
                      >
                        <Minus class="w-3 h-3" />
                      </button>
                      <input 
                        type="number" 
                        v-model.number="disk.size"
                        class="w-16 h-7 text-center border-t border-b border-gray-300 text-sm focus:outline-none"
                      />
                      <button 
                        @click="disk.size = Math.min(2000, disk.size + 10)"
                        class="w-7 h-7 flex items-center justify-center border border-gray-300 text-gray-600 hover:bg-gray-100 transition-colors"
                      >
                        <Plus class="w-3 h-3" />
                      </button>
                      <span class="text-sm text-gray-600 ml-1">GB</span>
                    </div>
                    <div class="relative">
                      <select 
                        v-model="disk.type"
                        class="px-3 py-1.5 border border-gray-300 text-sm focus:outline-none focus:ring-2 focus:ring-flame-500/20 focus:border-flame-500 pr-8 appearance-none cursor-pointer"
                      >
                        <option v-for="type in diskTypes" :key="type" :value="type">
                          {{ type }}
                        </option>
                      </select>
                      <ChevronDown class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- 网络配置 -->
        <div class="bg-white border border-gray-100">
          <div class="px-6 py-4 border-b border-gray-100 flex items-center gap-2">
            <Shield class="w-5 h-5 text-flame-500" />
            <span class="font-medium text-gray-900">网络配置</span>
          </div>
          
          <div class="p-6 space-y-6">
            <!-- 私网 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0">私网</label>
              <div class="flex-1 flex items-center gap-3">
                <div class="relative flex-1 max-w-md">
                  <select 
                    v-model="selectedVpc"
                    class="w-full px-3 py-2 border border-gray-300 text-sm focus:outline-none focus:ring-2 focus:ring-flame-500/20 focus:border-flame-500 pr-8 appearance-none cursor-pointer"
                  >
                    <option value="" disabled>请选择</option>
                    <option v-for="vpc in privateNetworks" :key="vpc.value" :value="vpc.value">
                      {{ vpc.label }}
                    </option>
                  </select>
                  <ChevronDown class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                </div>
                <button class="text-sm text-flame-500 hover:text-flame-600 transition-colors whitespace-nowrap">
                  创建私有网络
                </button>
              </div>
            </div>

            <!-- 线路 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0">线路</label>
              <div class="flex-1">
                <div class="flex items-center gap-4">
                  <label 
                    v-for="line in lineTypes" 
                    :key="line"
                    :class="[
                      'flex items-center gap-2 cursor-pointer px-3 py-1.5 border text-sm',
                      selectedLine === line 
                        ? 'border-flame-500 text-flame-500 bg-flame-50' 
                        : 'border-gray-300 text-gray-700 hover:border-gray-400'
                    ]"
                  >
                    <input 
                      type="radio" 
                      :value="line" 
                      v-model="selectedLine"
                      class="hidden"
                    />
                    {{ line }}
                  </label>
                </div>
              </div>
            </div>

            <!-- 带宽 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0">带宽</label>
              <div class="flex-1 flex items-center gap-3">
                <div class="flex-1 max-w-md">
                  <input 
                    type="range" 
                    v-model.number="bandwidth"
                    :min="minBandwidth"
                    :max="maxBandwidth"
                    class="w-full h-1 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-flame-500"
                  />
                </div>
                <div class="flex items-center gap-1">
                  <button 
                    @click="decreaseBandwidth"
                    class="w-7 h-7 flex items-center justify-center border border-gray-300 text-gray-600 hover:bg-gray-100 transition-colors"
                  >
                    <Minus class="w-3 h-3" />
                  </button>
                  <input 
                    type="number" 
                    v-model.number="bandwidth"
                    class="w-14 h-7 text-center border-t border-b border-gray-300 text-sm focus:outline-none"
                  />
                  <button 
                    @click="increaseBandwidth"
                    class="w-7 h-7 flex items-center justify-center border border-gray-300 text-gray-600 hover:bg-gray-100 transition-colors"
                  >
                    <Plus class="w-3 h-3" />
                  </button>
                  <span class="text-sm text-gray-600 ml-1">Mbit/s</span>
                </div>
              </div>
            </div>

            <!-- 公网IP -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0"></label>
              <div class="flex-1">
                <label class="flex items-center gap-2 cursor-pointer">
                  <input 
                    type="checkbox" 
                    v-model="hasPublicIp"
                    class="w-4 h-4 text-flame-500 border-gray-300 rounded focus:ring-flame-500"
                  />
                  <span class="text-sm text-gray-600">
                    免费赠送公网 ({{ selectedLine }}) IP 1 个
                  </span>
                </label>
              </div>
            </div>
          </div>
        </div>

        <!-- 高级配置 -->
        <div class="bg-white border border-gray-100">
          <div class="px-6 py-4 border-b border-gray-100 flex items-center gap-2">
            <Settings class="w-5 h-5 text-flame-500" />
            <span class="font-medium text-gray-900">高级配置</span>
          </div>
          
          <div class="p-6 space-y-6">
            <!-- 密码设置 -->
            <div class="flex items-start gap-6">
              <label class="w-20 text-sm text-gray-700 pt-2 flex-shrink-0"></label>
              <div class="flex-1">
                <div class="flex items-center gap-4 mb-4">
                  <label 
                    v-for="mode in passwordModes" 
