<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { Search, RefreshCw, ChevronDown, ChevronUp, ChevronLeft, ChevronRight, Users, Link, User } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { useRouter } from 'vue-router'

const router = useRouter()

interface PromoUser {
  id: number
  uid: string
  phone: string
  username: string
  vm_count: number
  register_time: string
  last_login: string
  personal_verified: number
  enterprise_verified: number
  status: number
}

const users = ref<PromoUser[]>([])
const loading = ref(false)
const showFilters = ref(false)
const searchField = ref('phone')
const searchKeyword = ref('')

const currentPage = ref(1)
const pageSize = ref(20)
const total = ref(0)

const statusMap: Record<number, { text: string; color: string }> = {
  0: { text: '禁用', color: 'bg-red-100 text-red-700' },
  1: { text: '正常', color: 'bg-green-100 text-green-700' },
}

const verifyMap: Record<number, { text: string; color: string }> = {
  0: { text: '未认证', color: 'bg-gray-100 text-gray-500' },
  1: { text: '已认证', color: 'bg-green-100 text-green-700' },
}

const searchFields = [
  { value: 'phone', label: '注册手机号' },
  { value: 'uid', label: '用户UID' },
  { value: 'username', label: '用户名' },
]

const mockUsers: PromoUser[] = [
  {
    id: 1, uid: '10001', phone: '13800138001', username: '用户A',
    vm_count: 3, register_time: '2024-07-20 10:00:00', last_login: '2024-07-24 09:30:00',
    personal_verified: 1, enterprise_verified: 0, status: 1,
  },
  {
    id: 2, uid: '10002', phone: '13800138002', username: '用户B',
    vm_count: 1, register_time: '2024-07-19 14:20:00', last_login: '2024-07-23 16:45:00',
    personal_verified: 1, enterprise_verified: 1, status: 1,
  },
  {
    id: 3, uid: '10003', phone: '13800138003', username: '用户C',
    vm_count: 0, register_time: '2024-07-18 09:10:00', last_login: '2024-07-20 11:00:00',
    personal_verified: 0, enterprise_verified: 0, status: 1,
  },
  {
    id: 4, uid: '10004', phone: '13800138004', username: '用户D',
    vm_count: 2, register_time: '2024-07-17 16:30:00', last_login: '2024-07-24 08:00:00',
    personal_verified: 1, enterprise_verified: 0, status: 0,
  },
  {
    id: 5, uid: '10005', phone: '13800138005', username: '用户E',
    vm_count: 5, register_time: '2024-07-15 11:45:00', last_login: '2024-07-24 10:15:00',
    personal_verified: 1, enterprise_verified: 1, status: 1,
  },
]

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchUsers = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    users.value = mockUsers
    total.value = mockUsers.length
  } catch (e) {
    console.error('[fetchUsers] 异常', e)
  } finally {
    loading.value = false
  }
}

const handleSearch = () => {
  currentPage.value = 1
  fetchUsers()
}

const handleRefresh = () => {
  fetchUsers()
}

const goToPromoLink = () => {
  router.push('/console/user/promotion/link')
}

const prevPage = () => {
  if (currentPage.value > 1) {
    currentPage.value--
    fetchUsers()
  }
}

const nextPage = () => {
  const totalPages = Math.ceil(total.value / pageSize.value)
  if (currentPage.value < totalPages) {
    currentPage.value++
    fetchUsers()
  }
}

onMounted(() => {
  fetchUsers()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">我的推广</h1>
      <p class="text-gray-500 mt-1">查看您推广的用户列表</p>
    </div>

    <div class="p-6">
      <div class="bg-white border border-gray-100">
        <div class="p-4 border-b border-gray-100">
          <div class="flex items-center gap-2 flex-wrap">
            <button
              @click="goToPromoLink"
              class="flex items-center gap-2 px-4 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium transition-colors"
            >
              <Link class="w-4 h-4" />
              推广链接
            </button>

            <div class="relative">
              <select
                v-model="searchField"
                class="pl-3 pr-8 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none appearance-none cursor-pointer min-w-[120px]"
              >
                <option v-for="f in searchFields" :key="f.value" :value="f.value">{{ f.label }}</option>
              </select>
              <svg class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="6 9 12 15 18 9"></polyline>
              </svg>
            </div>

            <div class="relative">
              <input
                v-model="searchKeyword"
                type="text"
                placeholder="请输入"
                class="pl-3 pr-10 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none w-48"
                @keyup.enter="handleSearch"
              />
              <button
                @click="handleSearch"
                class="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-500"
              >
                <Search class="w-4 h-4" />
              </button>
            </div>

            <button
              @click="showFilters = !showFilters"
              class="flex items-center gap-1 px-3 py-1.5 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 transition-colors"
            >
              {{ showFilters ? '收起' : '展开' }}
              <ChevronDown v-if="!showFilters" class="w-4 h-4" />
              <ChevronUp v-else class="w-4 h-4" />
            </button>

            <button
              @click="handleRefresh"
              class="flex items-center gap-2 px-3 py-1.5 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 transition-colors"
            >
              <RefreshCw class="w-4 h-4" />
            </button>
          </div>

          <div v-if="showFilters" class="mt-4 pt-4 border-t border-gray-100 grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label class="block text-sm text-gray-600 mb-1">用户状态</label>
              <select class="w-full px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">
                <option value="">全部状态</option>
                <option value="1">正常</option>
                <option value="0">禁用</option>
              </select>
            </div>
            <div>
              <label class="block text-sm text-gray-600 mb-1">实名认证</label>
              <select class="w-full px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">
                <option value="">全部</option>
                <option value="personal">个人认证</option>
                <option value="enterprise">企业认证</option>
                <option value="none">未认证</option>
              </select>
            </div>
            <div>
              <label class="block text-sm text-gray-600 mb-1">注册时间</label>
              <div class="flex items-center gap-2">
                <input type="date" class="flex-1 px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none" />
                <span class="text-gray-400">至</span>
                <input type="date" class="flex-1 px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none" />
              </div>
            </div>
          </div>
        </div>

        <div class="overflow-x-auto">
          <table class="w-full min-w-max">
            <thead>
              <tr class="border-b border-gray-200 bg-gray-50">
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">用户UID</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">注册手机号</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">用户</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">云主机数量</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">注册时间</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">最后登录</th>
                <th class="px-4 py-3 text-center text-xs font-medium text-gray-500 whitespace-nowrap">个人</th>
                <th class="px-4 py-3 text-center text-xs font-medium text-gray-500 whitespace-nowrap">企业</th>
                <th class="px-4 py-3 text-center text-xs font-medium text-gray-500 whitespace-nowrap">状态</th>
              </tr>
            </thead>
            <tbody>
              <tr v-if="loading" class="border-b border-gray-100">
                <td colspan="9" class="px-4 py-12 text-center text-gray-400">
                  <RefreshCw class="w-6 h-6 animate-spin mx-auto mb-2" />
                  加载中...
                </td>
              </tr>
              <tr v-else-if="users.length === 0" class="border-b border-gray-100">
                <td colspan="9" class="px-4 py-12 text-center text-gray-400">
                  <Users class="w-12 h-12 text-gray-300 mx-auto mb-2" />
                  <p>无数据</p>
                </td>
              </tr>
              <tr
                v-for="user in users"
                :key="user.id"
                class="border-b border-gray-100 hover:bg-gray-50 transition-colors"
              >
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">{{ user.uid }}</td>
                <td class="px-4 py-3 text-sm text-gray-700 whitespace-nowrap">{{ user.phone }}</td>
                <td class="px-4 py-3 text-sm text-gray-700 whitespace-nowrap">{{ user.username }}</td>
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">{{ user.vm_count }}</td>
                <td class="px-4 py-3 text-sm text-gray-500 whitespace-nowrap">{{ user.register_time }}</td>
                <td class="px-4 py-3 text-sm text-gray-500 whitespace-nowrap">{{ user.last_login }}</td>
                <td class="px-4 py-3 text-center">
                  <span :class="['inline-flex items-center px-2 py-0.5 text-xs font-medium', verifyMap[user.personal_verified]?.color || 'bg-gray-100 text-gray-500']">
                    {{ verifyMap[user.personal_verified]?.text || '未认证' }}
                  </span>
                </td>
                <td class="px-4 py-3 text-center">
                  <span :class="['inline-flex items-center px-2 py-0.5 text-xs font-medium', verifyMap[user.enterprise_verified]?.color || 'bg-gray-100 text-gray-500']">
                    {{ verifyMap[user.enterprise_verified]?.text || '未认证' }}
                  </span>
                </td>
                <td class="px-4 py-3 text-center">
                  <span :class="['inline-flex items-center px-2 py-0.5 text-xs font-medium', statusMap[user.status]?.color || 'bg-gray-100 text-gray-500']">
                    {{ statusMap[user.status]?.text || '未知' }}
                  </span>
                </td>
              </tr>
            </tbody>
          </table>
        </div>

        <div class="px-4 py-4 border-t border-gray-100 flex items-center justify-between">
          <div class="text-sm text-gray-500">
            共 <span class="font-medium text-gray-700">{{ total }}</span> 条
          </div>
          <div class="flex items-center gap-2">
            <select
              v-model="pageSize"
              class="px-2 py-1 border border-gray-300 text-sm"
            >
              <option :value="10">10条/页</option>
              <option :value="20">20条/页</option>
              <option :value="50">50条/页</option>
              <option :value="100">100条/页</option>
            </select>

            <button
              @click="prevPage"
              :disabled="currentPage <= 1"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft class="w-4 h-4" />
            </button>

            <span class="text-sm text-gray-600">
              第 <span class="font-medium">{{ currentPage }}</span> 页
            </span>

            <button
              @click="nextPage"
              :disabled="currentPage >= Math.ceil(total / pageSize)"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight class="w-4 h-4" />
            </button>

            <span class="text-sm text-gray-500 ml-2">前往</span>
            <input
              v-model.number="currentPage"
              type="number"
              min="1"
              class="w-12 px-2 py-1 border border-gray-300 text-sm text-center"
            />
            <span class="text-sm text-gray-500">页</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
