<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { Search, RefreshCw, Receipt, ChevronLeft, ChevronRight } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'

interface RechargeOrder {
  id: number
  order_no: string
  amount: string
  pay_method: string
  status: number
  created_at: string
}

const orders = ref<RechargeOrder[]>([])
const loading = ref(false)
const searchKeyword = ref('')
const currentPage = ref(1)
const pageSize = ref(10)
const total = ref(0)

const statusMap: Record<number, { text: string; color: string }> = {
  0: { text: '待支付', color: 'bg-yellow-100 text-yellow-700' },
  1: { text: '已完成', color: 'bg-green-100 text-green-700' },
  2: { text: '已取消', color: 'bg-gray-100 text-gray-500' },
  3: { text: '审核中', color: 'bg-blue-100 text-blue-700' },
  4: { text: '已失败', color: 'bg-red-100 text-red-700' },
}

const payMethodMap: Record<string, string> = {
  alipay: '支付宝',
  wechat: '微信支付',
  bank_transfer: '银行转账',
  alipay_transfer: '支付宝转账',
  wechat_transfer: '微信转账',
}

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchOrders = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    const params = new URLSearchParams()
    params.set('page', String(currentPage.value))
    params.set('page_size', String(pageSize.value))
    if (searchKeyword.value) params.set('keyword', searchKeyword.value)
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.recharge.orders}?${params.toString()}`, {
      method: 'GET',
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      orders.value = data.data.list || []
      total.value = data.data.total || 0
    } else {
      orders.value = []
      total.value = 0
    }
  } catch (e) {
    console.error('[fetchOrders] 异常', e)
    orders.value = []
    total.value = 0
  } finally {
    loading.value = false
  }
}

const handleSearch = () => {
  currentPage.value = 1
  fetchOrders()
}

const handleRefresh = () => {
  fetchOrders()
}

const prevPage = () => {
  if (currentPage.value > 1) {
    currentPage.value--
    fetchOrders()
  }
}

const nextPage = () => {
  const totalPages = Math.ceil(total.value / pageSize.value)
  if (currentPage.value < totalPages) {
    currentPage.value++
    fetchOrders()
  }
}

onMounted(() => {
  fetchOrders()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">充值订单</h1>
      <p class="text-gray-500 mt-1">查看您的所有充值订单记录</p>
    </div>

    <div class="p-6 space-y-4">
      <div class="bg-white border border-gray-100 p-4">
        <div class="flex items-center justify-between flex-wrap gap-4">
          <div class="flex items-center gap-3">
            <div class="relative">
              <Search class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                v-model="searchKeyword"
                type="text"
                placeholder="搜索订单号"
                class="pl-10 pr-4 py-2 border border-gray-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-colors w-64"
                @keyup.enter="handleSearch"
              />
            </div>
            <button @click="handleSearch" class="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 text-sm font-medium transition-colors">
              搜索
            </button>
          </div>
          <button @click="handleRefresh" class="flex items-center gap-2 px-3 py-2 border border-gray-300 text-gray-600 hover:bg-gray-50 transition-colors text-sm">
            <RefreshCw class="w-4 h-4" />
            刷新
          </button>
        </div>
      </div>

      <div class="bg-white border border-gray-200">
        <table class="w-full" v-if="!loading">
          <thead>
            <tr class="border-b border-gray-200 bg-gray-50">
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">订单号</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">充值金额</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">支付方式</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">状态</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">创建时间</th>
              <th class="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase">操作</th>
            </tr>
          </thead>
          <tbody>
            <tr v-if="orders.length === 0">
              <td colspan="6" class="px-4 py-12 text-center text-gray-400">
                <Receipt class="w-12 h-12 text-gray-300 mx-auto mb-2" />
                <p>暂无充值订单</p>
              </td>
            </tr>
            <tr v-for="order in orders" :key="order.id" class="border-b border-gray-100 hover:bg-gray-50 transition-colors">
              <td class="px-4 py-3">
                <div class="text-sm font-medium text-gray-900 font-mono">{{ order.order_no }}</div>
              </td>
              <td class="px-4 py-3">
                <span class="text-lg font-bold text-flame-500">¥{{ order.amount }}</span>
              </td>
              <td class="px-4 py-3">
                <span class="text-sm text-gray-600">{{ payMethodMap[order.pay_method] || order.pay_method }}</span>
              </td>
              <td class="px-4 py-3">
                <span :class="['inline-flex items-center gap-1 px-2 py-0.5 text-xs font-medium', statusMap[order.status]?.color || 'bg-gray-100 text-gray-500']">
                  <span :class="['w-1.5 h-1.5 rounded-full', order.status === 1 ? 'bg-green-500' : order.status === 0 ? 'bg-yellow-500' : order.status === 3 ? 'bg-blue-500' : 'bg-gray-400']"></span>
                  {{ statusMap[order.status]?.text || '未知' }}
                </span>
              </td>
              <td class="px-4 py-3 text-sm text-gray-500">{{ order.created_at }}</td>
              <td class="px-4 py-3">
                <div class="flex items-center justify-end gap-2">
                  <button v-if="order.status === 0" class="px-2 py-1 text-xs text-blue-600 hover:bg-blue-50">去支付</button>
                  <button class="px-2 py-1 text-xs text-gray-600 hover:bg-gray-100">详情</button>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
        <div v-else class="px-4 py-12 text-center text-gray-400">加载中...</div>

        <div class="px-4 py-3 bg-gray-50 border-t border-gray-200 flex items-center justify-between">
          <div class="text-sm text-gray-500">
            共 <span class="font-medium text-gray-700">{{ total }}</span> 条记录
          </div>
          <div class="flex items-center gap-2">
            <button
              @click="prevPage"
              :disabled="currentPage <= 1"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft class="w-4 h-4" />
            </button>
            <span class="text-sm text-gray-600">
              第 <span class="font-medium">{{ currentPage }}</span> 页
            </span>
            <button
              @click="nextPage"
              :disabled="currentPage >= Math.ceil(total / pageSize)"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight class="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
