// 公告（来自后端 /v1/news/list，已发布的新闻公告）
interface Announcement {
  id: number
  title: string
  date: string
}
const announcements = ref<Announcement[]>([])

const fetchAnnouncements = async () => {
  try {
    const res = await fetch(API_BASE_URL + API_ENDPOINTS.news.list, {
      method: 'GET',
    })
    const data = await res.json()
    if (data.code === 0 && data.data?.list) {
      announcements.value = (data.data.list as Array<Record<string, unknown>>).map(
        (n) => ({
          id: Number(n.id) || 0,
          title: (n.title as string) || '',
          date: ((n.publish_time as string) || '').slice(0, 10),
        }),
      )
    }
  } catch {
    // 公告加载失败时静默保留空列表，不影响首页其它板块
  }
}

// 待办「待回复工单」数量：取 /v1/ticket/list 聚合的 processing。
// 后端 processing = status 0(待回复)+1(客户发送)+2(客服答复) 且 deleted_at IS NULL，
// 已结案关闭(3)与已删除的工单不计入，与工单列表页「服务中」统计同源。
const fetchPendingTicketCount = async () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.list}?page=1&page_size=1`, {
      method: 'GET',
      headers: { uid, token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      const item = todoItems.value.find((t) => t.title === '待回复工单')
      if (item) item.count = Number(data.data.processing) || 0
    }
  } catch {
    // 统计拉取失败时保留 0，不影响首页其它板块
  }
}

const getStatusIcon = (status: string) => {
  switch (status) {
    case 'success':
      return CheckCircle
    case 'warning':
      return AlertTriangle
    default:
      return Info
  }
}

const getStatusColor = (type: string) => {
  switch (type) {
    case 'success':
      return 'text-green-500 bg-green-50'
    case 'warning':
      return 'text-yellow-500 bg-yellow-50'
    default:
      return 'text-blue-500 bg-blue-50'
  }
}

const getIconColorClass = (color: string) => {
  const colorMap: Record<string, string> = {
    blue: 'bg-blue-50 text-blue-500',
    green: 'bg-green-50 text-green-500',
    purple: 'bg-purple-50 text-purple-500',
    orange: 'bg-orange-50 text-orange-500',
    teal: 'bg-teal-50 text-teal-500',
    pink: 'bg-pink-50 text-pink-500',
  }
  return colorMap[color] || 'bg-gray-50 text-gray-500'
}

const navigateTo = (path: string) => {
  router.push(path)
}

onMounted(() => {
  fetchUserInfo()
  fetchBalance()
  fetchAnnouncements()
  fetchPendingTicketCount()

  animate('.stat-card', {
    translateY: [30, 0],
    opacity: [0, 1],
    duration: 600,
    easing: 'easeOutQuad',
    delay: (el: HTMLElement, i: number) => i * 100
  })

  animate('.section-card', {
    translateY: [20, 0],
    opacity: [0, 1],
    duration: 500,
    easing: 'easeOutQuad',
    delay: (el: HTMLElement, i: number) => 400 + i * 80
  })
})
</script>

