69<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { 
  Server, Power, Settings, MoreVertical, Search, Filter, Plus, RefreshCw,
  FileText, ShieldCheck, Camera, Trash2,
  Edit
} from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

const route = useRoute()
const router = useRouter()

const activeTab = computed(() => {
  return (route.query.tab as string) || 'instances'
})

const tabs = [
  { key: 'instances', name: '实例列表', icon: Server },
  { key: 'security-group', name: '安全组', icon: ShieldCheck },
  { key: 'snapshots', name: '快照管理', icon: Camera },
]

const switchTab = (tab: string) => {
  router.push({ path: '/console/ecs', query: { tab } })
}

interface EcsInstance {
  id: string
  instance_id: string
  name: string
  instance_name: string
  region: string
  region_label: string
  status: string
  cpu: string
  memory: string
  public_ip: string
  private_ip: string
  os: string
  os_name: string
  remark: string
  created_at: string
}

const instances = ref<EcsInstance[]>([])
const loading = ref(false)

const searchQuery = ref('')
const selectedRegion = ref('all')
const regions = ['all', '华北-北京', '华东-上海', '华南-广州']

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchInstances = async () => {
  const auth = getAuthHeaders()
  if (!auth) return

  loading.value = true
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ecs.instance.list}`, {
      method: 'GET',
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data && data.data.list) {
      instances.value = data.data.list.map((item: any) => ({
        id: item.instance_id,
        instance_id: item.instance_id,
        name: item.instance_name || item.remark || 'ECS实例',
        instance_name: item.instance_name,
        region: item.region_label || item.region,
        region_label: item.region_label,
        status: item.status === 'running' ? 'running' : 'stopped',
        cpu: item.cpu,
        memory: item.memory,
        ip: item.public_ip || item.private_ip,
        public_ip: item.public_ip,
        private_ip: item.private_ip,
        os: item.os_name,
        os_name: item.os_name,
        remark: item.remark || '',
        created_at: item.created_at,
      }))
    }
  } catch (e) {
    console.error('[fetchInstances] 异常', e)
    toast.error('获取实例列表失败')
  } finally {
    loading.value = false
  }
}

const getStatusColor = (status: string) => {
  return status === 'running' ? 'bg-green-500' : 'bg-gray-400'
}

const getStatusText = (status: string) => {
  return status === 'running' ? '运行中' : '已停止'
}

onMounted(() => {
  if (activeTab.value === 'instances') {
    fetchInstances()
  }
})

const securityGroups = ref([
