const sgSearchQuery = ref('')
const selectedSg = ref<string | null>(null)
const sgRules = ref([
  { id: 'rule-001', sgId: 'sg-001', direction: '入方向', protocol: 'TCP', port: '22', source: '0.0.0.0/0', action: '允许', description: 'SSH远程连接' },
  { id: 'rule-002', sgId: 'sg-001', direction: '入方向', protocol: 'TCP', port: '80', source: '0.0.0.0/0', action: '允许', description: 'HTTP访问' },
