  { id: 'rule-004', sgId: 'sg-001', direction: '入方向', protocol: 'ICMP', port: '-', source: '0.0.0.0/0', action: '允许', description: 'Ping监控' },
  { id: 'rule-005', sgId: 'sg-001', direction: '出方向', protocol: 'ALL', port: '-', source: '0.0.0.0/0', action: '允许', description: '允许所有出站流量' },
  { id: 'rule-006', sgId: 'sg-002', direction: '入方向', protocol: 'TCP', port: '80', source: '0.0.0.0/0', action: '允许', description: 'HTTP' },
  { id: 'rule-007', sgId: 'sg-002', direction: '入方向', protocol: 'TCP', port: '443', source: '0.0.0.0/0', action: '允许', description: 'HTTPS' },
