<script setup lang="ts">
import { Download, X } from 'lucide-vue-next'
import QRCode from 'qrcode'
import { ref } from 'vue'
import { APP_DOWNLOAD_URL } from '@/config/app_release'

const isOpen = ref(false)
const qrDataUrl = ref('')

// 悬浮窗二维码：展示固定版本的 APP 下载直链，代替原客服入口图片
const toggle = async (): Promise<void> => {
  isOpen.value = !isOpen.value
  if (isOpen.value && !qrDataUrl.value) {
    qrDataUrl.value = await QRCode.toDataURL(APP_DOWNLOAD_URL, {
      width: 240,
      margin: 1,
      color: {
        dark: '#111827',
        light: '#ffffff',
      },
    })
  }
}
</script>

<template>
  <div class="fixed bottom-6 right-4 sm:right-6 z-40">
    <div
      v-if="isOpen"
      class="mb-4 glass-card p-4 w-60 sm:w-64 mr-0 sm:mr-0"
    >
      <div class="flex items-center justify-between mb-3">
        <span class="text-gray-900 dark:text-white font-semibold text-sm">下载 APP</span>
        <button @click="isOpen = false" class="text-gray-400 hover:text-gray-900 dark:text-gray-500 dark:hover:text-white">
          <X class="w-4 h-4" />
        </button>
      </div>
      <div class="space-y-3">
        <div class="text-center">
          <img
            v-if="qrDataUrl"
            :src="qrDataUrl"
            alt="APP 下载二维码"
            class="w-32 sm:w-36 aspect-square object-contain mx-auto rounded-lg"
          />
          <div v-else class="w-32 sm:w-36 aspect-square mx-auto rounded-lg bg-gray-100 dark:bg-dark-400 animate-pulse"></div>
        </div>
        <p class="text-gray-400 dark:text-gray-500 text-xs text-center">扫码下载 Android 最新版 APP</p>
        <a
          :href="APP_DOWNLOAD_URL"
          target="_blank"
          rel="noopener noreferrer"
          class="flex items-center justify-center gap-1.5 text-xs text-flame-500 hover:text-flame-600 transition-colors"
        >
          <Download class="w-3.5 h-3.5" />
          无法扫码？点击直接下载
        </a>
      </div>
    </div>

    <button
      @click="toggle"
      class="w-12 h-12 sm:w-14 sm:h-14 bg-flame-gradient rounded-full flex items-center justify-center shadow-lg shadow-flame-500/30 hover:shadow-flame-500/50 hover:scale-105 transition-all duration-300"
    >
      <Download class="w-5 h-5 sm:w-6 sm:h-6 text-white" />
    </button>
  </div>
</template>
