<script setup lang="ts">
import { ref, onMounted, onUnmounted } from 'vue'
import { Headphones } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'

const emit = defineEmits<{
  (e: 'click'): void
}>()

const online = ref(false)
let pollTimer: ReturnType<typeof setInterval> | null = null
const uid = localStorage.getItem('uid')
const token = localStorage.getItem('token')

const checkOnlineStatus = async () => {
  if (!uid || !token) return
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.chat.kfOnline}`, {
      headers: { 'uid': uid, 'token': token },
    })
    const data = await res.json()
    if (data.code === 0) {
      online.value = data.data.online
    }
  } catch {
    // 请求失败时保持上次状态
  }
}

const startPolling = () => {
  stopPolling()
  checkOnlineStatus()
  pollTimer = setInterval(checkOnlineStatus, 5000)
}

const stopPolling = () => {
  if (pollTimer) {
    clearInterval(pollTimer)
    pollTimer = null
  }
}

onMounted(() => {
  startPolling()
})

onUnmounted(() => {
  stopPolling()
})
</script>

<template>
  <button
    @click="emit('click')"
    class="flex items-center gap-1.5 px-3 py-2 text-sm transition-colors relative"
    :class="online ? 'text-green-500 hover:text-green-400' : 'text-gray-400 hover:text-gray-300'"
    :title="online ? '客服在线' : '客服离线'"
  >
    <span class="relative flex items-center">
      <Headphones class="w-4 h-4" />
      <span
        class="absolute -top-0.5 -right-0.5 w-2 h-2 rounded-full border border-white"
        :class="online ? 'bg-green-500' : 'bg-gray-400'"
      ></span>
    </span>
    <span class="hidden sm:inline">客服</span>
  </button>
</template>