// ==================== 资源包列表 ====================
const resBags = ref([
  {
    id: 'rbag-001',
    name: '块存储包-生产环境',
    type: '块存储包',
    usedSize: 180,
    totalSize: 200,
    region: '华东1（杭州）',
    status: 'active',
    payType: '包年包月',
    effectiveTime: '2025-07-01 00:00:00',
    expireTime: '2025-10-01 00:00:00',
    description: '生产环境块存储抵扣包'
  },
  {
    id: 'rbag-002',
    name: '对象存储包-备份',
    type: '对象存储包',
    usedSize: 350,
    totalSize: 500,
    region: '华东1（杭州）',
    status: 'active',
    payType: '包年包月',
    effectiveTime: '2025-06-15 00:00:00',
    expireTime: '2026-06-15 00:00:00',
    description: '备份存储抵扣包'
  },
  {
    id: 'rbag-003',
    name: '块存储包-测试',
    type: '块存储包',
    usedSize: 20,
    totalSize: 40,
    region: '华北1（青岛）',
    status: 'expired',
    payType: '包年包月',
    effectiveTime: '2025-01-01 00:00:00',
    expireTime: '2025-04-01 00:00:00',
    description: '测试环境块存储抵扣包'
  },
])

const searchQuery = ref('')
const statusFilter = ref('all')

const regionOptions = ['华东1（杭州）', '华东2（上海）', '华北1（青岛）', '华北2（北京）', '华南1（深圳）']
const periodOptions = ['1个月', '2个月', '3个月', '6个月', '1年', '2年', '3年']

// 块存储包规格及价格（元/月）
const blockSpecOptions = [
  { size: 20, price: 20 },
  { size: 40, price: 40 },
  { size: 100, price: 100 },
  { size: 200, price: 200 },
  { size: 500, price: 500 },
]

// 对象存储包规格及价格（元/月）
const ossSpecOptions = [
  { size: 100, price: 10 },
  { size: 500, price: 45 },
  { size: 1024, price: 85 },
  { size: 5120, price: 400 },
  { size: 10240, price: 750 },
]

// 抵扣因子说明
const deductionFactors = [
  { type: 'SSD云盘', factor: 1, note: '20 GB = 20 GB' },
  { type: '高效云盘', factor: 0.35, note: '20 GB / 0.35 = 57.14 GB' },
  { type: '普通云盘', factor: 0.12, note: '20 GB / 0.12 = 166.67 GB' },
  { type: 'ESSD云盘', factor: 1.5, note: '20 GB / 1.5 = 13.33 GB' },
]

const buyForm = ref({
  name: 'resbag-default',
  type: 'block' as 'block' | 'oss',
  effectiveTime: 'immediate' as 'immediate' | 'scheduled',
  scheduledTime: '',
  spec: 20,
  region: '华东1（杭州）',
  description: '',
  quantity: 3,
  period: '1个月',
})

const getResBagStatusText = (status: string) => {
  return status === 'active' ? '有效' : status === 'expired' ? '已失效' : '已停用'
}

const getResBagStatusColor = (status: string) => {
  return status === 'active' ? 'bg-green-500' : 'bg-gray-400'
}

const currentSpecOptions = computed(() => {
  return buyForm.value.type === 'block' ? blockSpecOptions : ossSpecOptions
})

const currentPrice = computed(() => {
  const specs = buyForm.value.type === 'block' ? blockSpecOptions : ossSpecOptions
  const spec = specs.find(s => s.size === buyForm.value.spec) || specs[0]
  return spec.price
})

// 周期倍率
const periodMultiplier = computed(() => {
  const map: Record<string, number> = {
    '1个月': 1,
    '2个月': 2,
    '3个月': 3,
    '6个月': 6,
    '1年': 12,
    '2年': 24,
    '3年': 36,
  }
  return map[buyForm.value.period] || 1
})

const totalPrice = computed(() => {
  return (currentPrice.value * buyForm.value.quantity * periodMultiplier.value).toFixed(2)
})

const buyResBag = () => {
  const specItem = currentSpecOptions.value.find(s => s.size === buyForm.value.spec)
  const now = new Date()
  const expire = new Date(now)
  const months = periodMultiplier.value
  expire.setMonth(expire.getMonth() + months)

  for (let i = 0; i < buyForm.value.quantity; i++) {
    resBags.value.unshift({
      id: `rbag-${String(resBags.value.length + 1 + i).padStart(3, '0')}`,
      name: buyForm.value.name || `资源包-${String(resBags.value.length + 1 + i).padStart(3, '0')}`,
      type: buyForm.value.type === 'block' ? '块存储包' : '对象存储包',
      usedSize: 0,
      totalSize: buyForm.value.spec,
      region: buyForm.value.region,
      status: 'active',
      payType: '包年包月',
      effectiveTime: buyForm.value.effectiveTime === 'immediate'
        ? now.toLocaleString('zh-CN')
        : buyForm.value.scheduledTime,
      expireTime: expire.toLocaleString('zh-CN'),
      description: buyForm.value.description
    })
  }
  resBagView.value = 'list'
  resetForm()
}

const resetForm = () => {
  buyForm.value = {
    name: 'resbag-default',
    type: 'block',
    effectiveTime: 'immediate',
    scheduledTime: '',
    spec: 20,
    region: '华东1（杭州）',
    description: '',
    quantity: 3,
    period: '1个月',
  }
}

const filteredResBags = computed(() => {
  return resBags.value.filter(bag => {
    const matchSearch = !searchQuery.value ||
      bag.name.includes(searchQuery.value) ||
      bag.id.includes(searchQuery.value)
    const matchStatus = statusFilter.value === 'all' || bag.status === statusFilter.value
    return matchSearch && matchStatus
  })
})

// 切换资源包类型时重置规格为第一个选项
const handleTypeChange = (type: 'block' | 'oss') => {
  buyForm.value.type = type
  const specs = type === 'block' ? blockSpecOptions : ossSpecOptions
  buyForm.value.spec = specs[0].size
}
</script>

