<script setup lang="ts">
import { ref, onMounted, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { ChevronLeft } from 'lucide-vue-next'

const route = useRoute()
const router = useRouter()

interface NewsDetail {
  id: number
  title: string
  summary: string
  cover_image: string
  content: string
  source: string
  author: string
  publish_time: string
}

const detail = ref<NewsDetail | null>(null)
const loading = ref(false)
const errorMsg = ref('')

const load = async (id: number) => {
  if (!id) {
    errorMsg.value = '参数错误'
    return
  }
  loading.value = true
  errorMsg.value = ''
  detail.value = null
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.news.detail}?id=${id}`, {
      method: 'GET',
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      const d = data.data as Record<string, unknown>
      detail.value = {
        id: Number(d.id) || 0,
        title: (d.title as string) || '',
        summary: (d.summary as string) || '',
        cover_image: (d.cover_image as string) || '',
        content: (d.content as string) || '',
        source: (d.source as string) || '',
        author: (d.author as string) || '',
        publish_time: (d.publish_time as string) || '',
      }
    } else {
      errorMsg.value = (data.echo as string) || '公告不存在'
    }
  } catch {
    errorMsg.value = '网络错误，请稍后重试'
  } finally {
    loading.value = false
  }
}

onMounted(() => load(Number(route.params.id)))
watch(
  () => route.params.id,
  (val) => load(Number(val)),
)
</script>

<template>
  <div class="p-6">
    <button
      class="flex items-center gap-1 text-sm text-gray-500 hover:text-gray-700 mb-4"
      @click="router.back()"
    >
      <ChevronLeft class="w-4 h-4" /> 返回
    </button>

    <div v-if="loading" class="text-center text-gray-400 py-20">加载中…</div>
    <div v-else-if="errorMsg" class="text-center text-gray-400 py-20">{{ errorMsg }}</div>

    <article
      v-else-if="detail"
      class="max-w-3xl mx-auto bg-white border border-gray-100 rounded-xl p-6 sm:p-8"
    >
      <h1 class="text-2xl font-bold text-gray-900 leading-snug">{{ detail.title }}</h1>
      <div class="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-gray-400 mt-3">
        <span v-if="detail.source">来源：{{ detail.source }}</span>
        <span v-if="detail.author">作者：{{ detail.author }}</span>
        <span>{{ (detail.publish_time || '').slice(0, 16) }}</span>
      </div>
      <img
        v-if="detail.cover_image"
        :src="detail.cover_image"
        alt="封面"
        class="w-full rounded-xl mt-5 object-cover max-h-80"
      />
      <!-- 富文本正文：内容由后台管理员配置，统一由 .rich-content 样式约束响应式排版 -->
      <div class="rich-content mt-6" v-html="detail.content"></div>
    </article>
  </div>
</template>
