<script setup lang="ts">
import { ref, watch, onMounted, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { AlertCircle, Wallet, Upload, Clock, CreditCard, Building2, FileText, User } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

const route = useRoute()
const router = useRouter()

const getInitialTab = (): 'online' | 'offline' => {
  const tab = route.query.tab
  if (tab === 'offline') return 'offline'
  return 'online'
}

const activeTab = ref<'online' | 'offline'>(getInitialTab())

watch(() => route.fullPath, () => {
  activeTab.value = getInitialTab()
})

const currentBalance = ref('0.00')
const rechargeAmount = ref('')
const selectedPayment = ref('alipay')
const loading = ref(false)

const paymentMethods = [
  { key: 'alipay', name: '支付宝', icon: 'alipay' },
  { key: 'wechat', name: '微信支付', icon: 'wechat' },
]

const formatDateTimeLocal = (date: Date): string => {
  const pad = (n: number) => n.toString().padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`
}

const offlineForm = ref({
  remitMethod: '',
  amount: '',
  accountName: '',
  bankAccount: '',
  bankName: '',
  transactionId: '',
  remitTime: formatDateTimeLocal(new Date()),
  remark: '',
})

const remitMethods = [
  { value: 'bank_transfer', label: '银行转账' },
  { value: 'alipay_transfer', label: '支付宝转账' },
  { value: 'wechat_transfer', label: '微信转账' },
]

// 仅银行转账需要银行账户和支付银行；支付宝转账/微信转账等非银行转账方式不显示
const showBankFields = computed(() => offlineForm.value.remitMethod === 'bank_transfer')

const uploadedFiles = ref<Array<{ name: string; url: string; hash: string }>>([])
const uploading = ref(false)

const onlineAmountError = ref('')
const offlineAmountError = ref('')

const sanitizeAmount = (value: string): string => {
  let result = value.replace(/[^\d.]/g, '')
  const firstDotIndex = result.indexOf('.')
  if (firstDotIndex !== -1) {
    result = result.slice(0, firstDotIndex + 1) + result.slice(firstDotIndex + 1).replace(/\./g, '')
  }
  return result
}

const handleOnlineAmountInput = (event: Event) => {
  const target = event.target as HTMLInputElement
  const sanitized = sanitizeAmount(target.value)
  rechargeAmount.value = sanitized
  target.value = sanitized
  validateOnlineAmount()
}

const handleOfflineAmountInput = (event: Event) => {
  const target = event.target as HTMLInputElement
  const sanitized = sanitizeAmount(target.value)
  offlineForm.value.amount = sanitized
  target.value = sanitized
  validateOfflineAmount()
}

const validateOnlineAmount = () => {
  const val = rechargeAmount.value
  if (!val || val.trim() === '') {
    onlineAmountError.value = '请输入充值金额'
    return false
  }
  const num = parseFloat(val)
  if (isNaN(num)) {
    onlineAmountError.value = '请输入有效的数字金额'
    return false
  }
  if (num <= 0) {
    onlineAmountError.value = '充值金额必须大于 0'
    return false
  }
  if (num > 6000) {
    onlineAmountError.value = '微信商户平台单笔单日限额6000元，请选择其他方式充值'
    return false
  }
  onlineAmountError.value = ''
  return true
}

const validateOfflineAmount = () => {
  const val = offlineForm.value.amount
  if (!val || val.trim() === '') {
    offlineAmountError.value = '请输入充值金额'
    return false
  }
  const num = parseFloat(val)
  if (isNaN(num)) {
    offlineAmountError.value = '请输入有效的数字金额'
    return false
  }
  if (num <= 0) {
    offlineAmountError.value = '充值金额必须大于 0'
    return false
  }
  offlineAmountError.value = ''
  return true
}

watch(rechargeAmount, () => {
  validateOnlineAmount()
})

watch(() => offlineForm.value.amount, () => {
  validateOfflineAmount()
})

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchBalance = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.info}`, {
      method: 'GET',
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      currentBalance.value = data.data.balance || '0.00'
    }
  } catch (e) {
    console.error('[fetchBalance] 异常', e)
  }
}

const handleOnlineRecharge = async () => {
  const amount = parseFloat(rechargeAmount.value)
  if (isNaN(amount) || amount <= 0) {
    toast.error('请输入有效的充值金额')
    return
  }
  if (amount > 6000) {
    toast.error('微信商户平台单笔单日限额6000元，请选择其他方式充值')
    return
  }
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }
  loading.value = true
  try {
    const body = new URLSearchParams()
    body.set('amount', rechargeAmount.value)
    body.set('pay_method', selectedPayment.value)
    const aff = localStorage.getItem('promotion_aff') || ''
    if (aff) {
      body.set('aff', aff)
    }
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.recharge.online}`, {
      method: 'POST',
      headers: {
        'uid': auth.uid,
        'token': auth.token,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: body.toString(),
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('充值订单已创建，请等待支付')
      rechargeAmount.value = ''
      fetchBalance()
    } else {
      toast.error(data.echo || '下单失败')
    }
  } catch (e) {
    console.error('[handleOnlineRecharge] 异常', e)
    toast.error('下单失败')
  } finally {
    loading.value = false
  }
}

const handleOfflineRecharge = async () => {
  if (!offlineForm.value.remitMethod) {
    toast.error('请选择汇款方式')
    return
  }
  if (!offlineForm.value.amount || parseFloat(offlineForm.value.amount) <= 0) {
    toast.error('请输入有效的充值金额')
    return
  }
  if (!offlineForm.value.transactionId) {
    toast.error('请输入交易流水号')
    return
  }
  if (!offlineForm.value.remitTime) {
    toast.error('请选择汇款时间')
    return
  }
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }
  loading.value = true
  try {
    const body = new URLSearchParams()
    body.set('remit_method', offlineForm.value.remitMethod)
    body.set('amount', offlineForm.value.amount)
    body.set('account_name', offlineForm.value.accountName)
    body.set('bank_account', offlineForm.value.bankAccount)
    body.set('bank_name', offlineForm.value.bankName)
    body.set('transaction_id', offlineForm.value.transactionId)
    body.set('remit_time', offlineForm.value.remitTime)
    body.set('remark', offlineForm.value.remark)
    if (uploadedFiles.value.length > 0) {
      body.set('voucher', JSON.stringify(uploadedFiles.value))
    }
    const aff = localStorage.getItem('promotion_aff') || ''
    if (aff) {
      body.set('aff', aff)
    }
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.recharge.offline}`, {
      method: 'POST',
      headers: {
        'uid': auth.uid,
        'token': auth.token,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: body.toString(),
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('线下充值申请已提交，请等待审核')
      offlineForm.value = {
        remitMethod: '',
        amount: '',
        accountName: '',
        bankAccount: '',
        bankName: '',
        transactionId: '',
        remitTime: formatDateTimeLocal(new Date()),
        remark: '',
      }
      uploadedFiles.value = []
    } else {
      toast.error(data.echo || '提交失败')
    }
  } catch (e) {
    console.error('[handleOfflineRecharge] 异常', e)
    toast.error('提交失败')
  } finally {
    loading.value = false
  }
}

const handleFileUpload = async (event: Event) => {
  const target = event.target as HTMLInputElement
  const files = target.files
  if (!files) return
  for (let i = 0; i < files.length; i++) {
    const file = files[i]
    if (file.size > 10 * 1024 * 1024) {
      toast.error('图片大小不能超过10MB')
      continue
    }
    if (!/\.(jpg|jpeg|png)$/i.test(file.name)) {
      toast.error('只支持jpg、jpeg、png格式')
      continue
    }
    if (uploadedFiles.value.length >= 5) {
      toast.error('最多上传5张图片')
      continue
    }
    try {
      uploading.value = true
      const auth = getAuthHeaders()
      if (!auth) {
        toast.error('请先登录')
        return
      }
      const tokenRes = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.avatar}/token`, {
        method: 'GET',
        headers: { 'uid': auth.uid, 'token': auth.token },
      })
      const tokenData = await tokenRes.json()
      if (tokenData.code !== 0) {
        toast.error(tokenData.echo || '获取上传地址失败')
        continue
      }
      const uploadUrl = tokenData.data.upload_url
      const formData = new FormData()
      formData.append('file', file)
      const uploadRes = await fetch(uploadUrl, {
        method: 'POST',
        body: formData,
      })
      const uploadData = await uploadRes.json()
      if (uploadData.code !== 0) {
        toast.error(uploadData.echo || '文件上传失败')
        continue
      }
      const hash = uploadData.data?.hash || uploadData.data
      const hashStr = typeof hash === 'string' ? hash : String(hash)
      // 远程仅回传 hash，需调用后端 /v1/user/file/upload 用 hash 换取实际可访问的 URL
      const urlRes = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.file.upload}`, {
        method: 'POST',
        headers: {
          'uid': auth.uid,
          'token': auth.token,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: `hash=${encodeURIComponent(hashStr)}`,
      })
      const urlData = await urlRes.json()
      if (urlData.code !== 0) {
        toast.error(urlData.echo || '获取文件地址失败')
        continue
      }
      const realUrl = urlData.data?.url || ''
      uploadedFiles.value.push({
        name: file.name,
        url: realUrl,
        hash: hashStr,
      })
    } catch (e) {
      console.error('[voucherUpload] 异常', e)
      toast.error('文件上传失败')
    } finally {
      uploading.value = false
      if (target) target.value = ''
    }
  }
}

const removeFile = (index: number) => {
  uploadedFiles.value.splice(index, 1)
}

const switchTab = (tab: 'online' | 'offline') => {
  activeTab.value = tab
  router.push({ path: '/console/user/recharge', query: { tab } })
}

onMounted(() => {
  fetchBalance()
})
</script>

