                      <path d="M12 7c-3.3 0-6 2.2-6 5 0 1.5.8 2.8 2 3.7l-.5 1.8 2-1c.8.2 1.6.3 2.5.3 3.3 0 6-2.2 6-5s-2.7-4.8-6-4.8z" fill="white"/>
