<script setup lang="ts">
import { ref, onMounted, watch } from 'vue'
import { Upload, ShieldCheck, User, Building2, CheckCircle2, XCircle, Clock, AlertCircle, Pencil } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const loading = ref(false)
const submitting = ref(false)
const verificationType = ref<'1' | '2'>('1')

const verificationData = ref<any>(null)
const statusText = ref('')
const statusIcon = ref('')
const statusClass = ref('')

const personalForm = ref({
  real_name: '',
  id_card: '',
  id_card_front: '',
  id_card_back: '',
  phone: '',
})

const enterpriseForm = ref({
  real_name: '',
  id_card: '',
  id_card_front: '',
  id_card_back: '',
  company_name: '',
  business_license: '',
  legal_person: '',
  credit_code: '',
  phone: '',
})

const personalImageUrls = ref<Record<string, string>>({})
const enterpriseImageUrls = ref<Record<string, string>>({})

const showModifyButton = ref(false)
const isModifying = ref(false)

const sharedFields = ['real_name', 'id_card', 'id_card_front', 'id_card_back', 'phone'] as const

watch(
  verificationType,
  (newType, oldType) => {
    const source = oldType === '1' ? personalForm.value : oldType === '2' ? enterpriseForm.value : null
    const target = newType === '1' ? personalForm.value : newType === '2' ? enterpriseForm.value : null
    const sourceUrls = oldType === '1' ? personalImageUrls.value : oldType === '2' ? enterpriseImageUrls.value : null
    const targetUrls = newType === '1' ? personalImageUrls.value : newType === '2' ? enterpriseImageUrls.value : null

    if (source && target) {
      for (const f of sharedFields) {
        if ((source as any)[f] && !(target as any)[f]) {
          (target as any)[f] = (source as any)[f]
        }
      }
    }
    if (sourceUrls && targetUrls) {
      for (const f of ['id_card_front', 'id_card_back']) {
        if ((sourceUrls as any)[f] && !(targetUrls as any)[f]) {
          (targetUrls as any)[f] = (sourceUrls as any)[f]
        }
      }
    }
  }
)

const resolveHash = async (hash: string): Promise<string> => {
  if (!hash) return ''
  const auth = getAuthHeaders()
  if (!auth) return ''

  try {
    const params = new URLSearchParams()
    params.append('hash', hash)
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.verification.uploadResolve}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'uid': auth.uid,
        'token': auth.token,
      },
      body: params.toString(),
    })
    const data = await res.json()
    if (data.code === 0) {
      return data.data.url || ''
    }
  } catch (e) {
    console.error('[resolveHash]', e)
  }
  return ''
}

const uploadFile = async (file: File): Promise<string> => {
  const auth = getAuthHeaders()
  if (!auth) throw new Error('未登录')

  const tokenRes = await fetch(`${API_BASE_URL}${API_ENDPOINTS.verification.uploadToken}`, {
    headers: { 'uid': auth.uid, 'token': auth.token },
  })
  const tokenData = await tokenRes.json()
  if (tokenData.code !== 0) throw new Error(tokenData.echo || '获取上传地址失败')

  const uploadUrl = tokenData.data.upload_url
  const fd = new FormData()
  fd.append('file', file)
  const uploadRes = await fetch(uploadUrl, { method: 'POST', body: fd })
  const uploadData = await uploadRes.json()
  if (uploadData.code !== 0) throw new Error(uploadData.echo || '上传失败')

  const hash = uploadData.data.hash || uploadData.data
  return hash
}

const handleUpload = async (field: string, event: Event) => {
  const target = event.target as HTMLInputElement
  const file = target.files?.[0]
  if (!file) return

  try {
    const hash = await uploadFile(file)
    const url = await resolveHash(hash)
    if (verificationType.value === '1') {
      (personalForm.value as any)[field] = hash
      personalImageUrls.value[field] = url
    } else {
      (enterpriseForm.value as any)[field] = hash
      enterpriseImageUrls.value[field] = url
    }
    toast.success('上传成功')
  } catch (e: any) {
    toast.error(e.message || '上传失败')
  }
  target.value = ''
}

const resolveAllImages = async () => {
  const form = verificationType.value === '1' ? personalForm.value : enterpriseForm.value
  const imageUrls = verificationType.value === '1' ? personalImageUrls.value : enterpriseImageUrls.value

  const imageFields = [
    'id_card_front',
    'id_card_back',
    'business_license',
  ]

  for (const field of imageFields) {
    const hash = (form as any)[field]
    if (hash && !imageUrls[field]) {
      const url = await resolveHash(hash)
      if (url) {
        imageUrls[field] = url
      }
    }
  }
}

const fetchVerification = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.verification.info}`, {
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0) {
      verificationData.value = data.data
      if (data.data) {
        const status = String(data.data.status)
        verificationType.value = String(data.data.type || '1') as '1' | '2'

        if (status === '0') {
          statusText.value = '审核中'
          statusIcon.value = 'clock'
          statusClass.value = 'bg-blue-50 text-blue-700 border-blue-200'
        } else if (status === '1') {
          statusText.value = '已通过'
          statusIcon.value = 'check'
          statusClass.value = 'bg-green-50 text-green-700 border-green-200'
          showModifyButton.value = true
        } else if (status === '2') {
          statusText.value = '已拒绝'
          statusIcon.value = 'x'
          statusClass.value = 'bg-red-50 text-red-700 border-red-200'
        }

        if (verificationType.value === '1') {
          personalForm.value.real_name = data.data.real_name || ''
          personalForm.value.id_card = data.data.id_card || ''
          personalForm.value.id_card_front = data.data.id_card_front || ''
          personalForm.value.id_card_back = data.data.id_card_back || ''
          personalForm.value.phone = data.data.phone || ''
        } else {
          enterpriseForm.value.real_name = data.data.real_name || ''
          enterpriseForm.value.id_card = data.data.id_card || ''
          enterpriseForm.value.id_card_front = data.data.id_card_front || ''
          enterpriseForm.value.id_card_back = data.data.id_card_back || ''
          enterpriseForm.value.company_name = data.data.company_name || ''
          enterpriseForm.value.business_license = data.data.business_license || ''
          enterpriseForm.value.legal_person = data.data.legal_person || ''
          enterpriseForm.value.credit_code = data.data.credit_code || ''
          enterpriseForm.value.phone = data.data.phone || ''
        }
        resolveAllImages()
      }
    }
  } catch (e) {
    console.error('[fetchVerification]', e)
  } finally {
    loading.value = false
  }
}

const submitVerification = async () => {
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }

  const form = verificationType.value === '1' ? personalForm.value : enterpriseForm.value

  if (!form.real_name) {
    toast.error('请输入真实姓名')
    return
  }
  if (!form.id_card) {
    toast.error('请输入身份证号')
    return
  }
  if (!form.id_card_front) {
    toast.error('请上传身份证正面')
    return
  }
  if (!form.id_card_back) {
    toast.error('请上传身份证背面')
    return
  }

  if (verificationType.value === '2') {
    if (!(form as any).company_name) {
      toast.error('请输入企业名称')
      return
    }
    if (!(form as any).business_license) {
      toast.error('请上传营业执照')
      return
    }
    if (!(form as any).credit_code) {
      toast.error('请输入统一社会信用代码')
      return
    }
  }

  submitting.value = true
  try {
    const params = new URLSearchParams()
    params.append('type', verificationType.value)
    params.append('real_name', form.real_name)
    params.append('id_card', form.id_card)
    params.append('id_card_front', form.id_card_front)
    params.append('id_card_back', form.id_card_back)
    params.append('phone', form.phone || '')

    if (verificationType.value === '2') {
      params.append('company_name', (form as any).company_name || '')
      params.append('business_license', (form as any).business_license || '')
      params.append('legal_person', (form as any).legal_person || '')
      params.append('credit_code', (form as any).credit_code || '')
    }

    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.verification.submit}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'uid': auth.uid,
        'token': auth.token,
      },
      body: params.toString(),
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('提交成功')
      await fetchVerification()
    } else {
      toast.error(data.echo || '提交失败')
    }
  } catch (e) {
    console.error('[submitVerification]', e)
    toast.error('提交失败')
  } finally {
    submitting.value = false
  }
}

const updateVerification = async () => {
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }

  const form = verificationType.value === '1' ? personalForm.value : enterpriseForm.value

  if (!form.real_name) {
    toast.error('请输入真实姓名')
    return
  }
  if (!form.id_card) {
    toast.error('请输入身份证号')
    return
  }
  if (!form.id_card_front) {
    toast.error('请上传身份证正面')
    return
  }
  if (!form.id_card_back) {
    toast.error('请上传身份证背面')
    return
  }

  if (verificationType.value === '2') {
    if (!(form as any).company_name) {
      toast.error('请输入企业名称')
      return
    }
    if (!(form as any).business_license) {
      toast.error('请上传营业执照')
      return
    }
    if (!(form as any).credit_code) {
      toast.error('请输入统一社会信用代码')
      return
    }
  }

  submitting.value = true
  try {
    const params = new URLSearchParams()
    params.append('type', verificationType.value)
    params.append('real_name', form.real_name)
    params.append('id_card', form.id_card)
    params.append('id_card_front', form.id_card_front)
    params.append('id_card_back', form.id_card_back)
    params.append('phone', form.phone || '')

    if (verificationType.value === '2') {
      params.append('company_name', (form as any).company_name || '')
      params.append('business_license', (form as any).business_license || '')
      params.append('legal_person', (form as any).legal_person || '')
      params.append('credit_code', (form as any).credit_code || '')
    }

    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.verification.update}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'uid': auth.uid,
        'token': auth.token,
      },
      body: params.toString(),
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('修改成功，已提交审核')
      isModifying.value = false
      showModifyButton.value = false
      await fetchVerification()
    } else {
      toast.error(data.echo || '修改失败')
    }
  } catch (e) {
    console.error('[updateVerification]', e)
    toast.error('修改失败')
  } finally {
    submitting.value = false
  }
}

const handleModify = () => {
  isModifying.value = true
  showModifyButton.value = false
  verificationData.value = null
  statusText.value = ''
  statusIcon.value = ''
  statusClass.value = ''
}

onMounted(() => {
  fetchVerification()
})
</script>

<template>
  <div>
    <div v-if="loading" class="flex items-center justify-center py-12">
      <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-orange-500"></div>
      <span class="ml-3 text-gray-700">加载中...</span>
    </div>

    <template v-else-if="verificationData && statusText && !showModifyButton">
      <div :class="['rounded-xl border p-6', statusClass]">
        <div class="flex items-start gap-4">
          <div class="flex-shrink-0 mt-0.5">
            <Clock v-if="statusIcon === 'clock'" class="w-8 h-8" />
            <CheckCircle2 v-else-if="statusIcon === 'check'" class="w-8 h-8" />
            <XCircle v-else-if="statusIcon === 'x'" class="w-8 h-8" />
          </div>
          <div class="flex-1">
            <h3 class="text-lg font-semibold">
              {{ verificationType === '1' ? '个人认证' : '企业认证' }} - {{ statusText }}
            </h3>
            <p v-if="statusText === '审核中'" class="text-sm mt-1 text-current">
              您的认证申请正在审核中，请耐心等待
            </p>
            <p v-else-if="statusText === '已通过'" class="text-sm mt-1 text-current">
              您的实名认证已通过审核
            </p>
            <p v-else-if="statusText === '已拒绝'" class="text-sm mt-1 text-current">
              您的认证申请未通过审核，请重新提交
            </p>
            <div v-if="verificationData.remark" class="mt-2 text-sm">
              <span class="font-medium">审核备注：</span>{{ verificationData.remark }}
            </div>
          </div>
        </div>
      </div>

      <div class="mt-6 bg-white rounded-xl border border-gray-200 p-6">
        <h3 class="font-semibold mb-4 text-gray-900">认证信息</h3>
        <div class="grid grid-cols-2 gap-4 text-sm text-gray-900">
          <div>
            <span class="text-gray-600 font-medium">认证类型：</span>
            <span>{{ verificationType === '1' ? '个人认证' : '企业认证' }}</span>
          </div>
          <div>
            <span class="text-gray-600 font-medium">真实姓名：</span>
            <span>{{ verificationData.real_name }}</span>
          </div>
          <div>
            <span class="text-gray-600 font-medium">身份证号：</span>
            <span>{{ verificationData.id_card }}</span>
          </div>
          <div>
            <span class="text-gray-600 font-medium">手机号：</span>
            <span>{{ verificationData.phone || '-' }}</span>
          </div>
          <template v-if="verificationType === '2'">
            <div>
              <span class="text-gray-600 font-medium">企业名称：</span>
              <span>{{ verificationData.company_name }}</span>
            </div>
            <div>
              <span class="text-gray-600 font-medium">统一社会信用代码：</span>
              <span>{{ verificationData.credit_code }}</span>
            </div>
            <div>
              <span class="text-gray-600 font-medium">法人代表：</span>
              <span>{{ verificationData.legal_person || '-' }}</span>
            </div>
          </template>
        </div>

        <div class="mt-4 grid grid-cols-2 gap-4">
          <div>
            <span class="text-sm text-gray-700 font-medium">身份证正面：</span>
            <div v-if="verificationType === '1' ? personalImageUrls.id_card_front : enterpriseImageUrls.id_card_front" class="mt-1">
              <img :src="verificationType === '1' ? personalImageUrls.id_card_front : enterpriseImageUrls.id_card_front" class="w-48 h-32 object-cover rounded border border-gray-200" />
            </div>
            <span v-else class="text-sm text-gray-500">-</span>
          </div>
          <div>
            <span class="text-sm text-gray-700 font-medium">身份证背面：</span>
            <div v-if="verificationType === '1' ? personalImageUrls.id_card_back : enterpriseImageUrls.id_card_back" class="mt-1">
              <img :src="verificationType === '1' ? personalImageUrls.id_card_back : enterpriseImageUrls.id_card_back" class="w-48 h-32 object-cover rounded border border-gray-200" />
            </div>
            <span v-else class="text-sm text-gray-500">-</span>
          </div>
          <template v-if="verificationType === '2'">
            <div>
              <span class="text-sm text-gray-700 font-medium">营业执照：</span>
              <div v-if="enterpriseImageUrls.business_license" class="mt-1">
                <img :src="enterpriseImageUrls.business_license" class="w-48 h-32 object-cover rounded border border-gray-200" />
              </div>
              <span v-else class="text-sm text-gray-500">-</span>
            </div>
          </template>
        </div>

        <div v-if="statusText === '已通过'" class="mt-6 flex justify-end">
          <button @click="handleModify" class="flame-btn flex items-center gap-2">
            <Pencil class="w-4 h-4" />
            <span>修改认证申请</span>
          </button>
        </div>
      </div>
    </template>

    <template v-else>
      <div class="bg-white rounded-xl border border-gray-200 p-6">
        <h3 class="text-lg font-semibold mb-1 text-gray-900">选择认证类型</h3>
        <p class="text-sm text-gray-600 mb-6">请选择您的认证方式</p>

        <div class="grid grid-cols-2 gap-4 mb-8">
          <button
            @click="verificationType = '1'"
            :class="[
              'p-6 rounded-xl border-2 text-left transition-all',
              verificationType === '1'
                ? 'border-flame-500 bg-flame-50 ring-2 ring-flame-500/20'
                : 'border-gray-200 bg-white hover:border-gray-400'
            ]"
          >
            <div class="flex items-center gap-3 mb-2">
              <div :class="[
                'w-10 h-10 rounded-lg flex items-center justify-center',
                verificationType === '1' ? 'bg-flame-500 text-white' : 'bg-gray-100 text-gray-600'
              ]">
                <User class="w-5 h-5" />
              </div>
              <span class="font-semibold text-gray-900">个人认证</span>
            </div>
            <p class="text-sm text-gray-600">适用于个人用户，需提供身份证信息</p>
          </button>

          <button
            @click="verificationType = '2'"
            :class="[
              'p-6 rounded-xl border-2 text-left transition-all',
              verificationType === '2'
                ? 'border-flame-500 bg-flame-50 ring-2 ring-flame-500/20'
                : 'border-gray-200 bg-white hover:border-gray-400'
            ]"
          >
            <div class="flex items-center gap-3 mb-2">
              <div :class="[
                'w-10 h-10 rounded-lg flex items-center justify-center',
                verificationType === '2' ? 'bg-flame-500 text-white' : 'bg-gray-100 text-gray-600'
              ]">
                <Building2 class="w-5 h-5" />
              </div>
              <span class="font-semibold text-gray-900">企业认证</span>
            </div>
            <p class="text-sm text-gray-600">适用于企业用户，需提供营业执照信息</p>
          </button>
        </div>

        <template v-if="verificationType === '1'">
          <h3 class="font-semibold mb-4 text-gray-900">个人认证信息</h3>
          <div class="space-y-4">
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-1.5">真实姓名 <span class="text-red-500">*</span></label>
              <input
                v-model="personalForm.real_name"
                type="text"
                class="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none"
                placeholder="请输入真实姓名"
              />
            </div>
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-1.5">身份证号 <span class="text-red-500">*</span></label>
              <input
                v-model="personalForm.id_card"
                type="text"
                class="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none"
                placeholder="请输入身份证号"
              />
            </div>
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-1.5">手机号</label>
              <input
                v-model="personalForm.phone"
                type="text"
                class="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none"
                placeholder="请输入手机号"
              />
            </div>
            <div class="grid grid-cols-2 gap-4">
              <div>
                <label class="block text-sm font-medium text-gray-700 mb-1.5">身份证正面 <span class="text-red-500">*</span></label>
                <label class="flex flex-col items-center justify-center h-32 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-orange-500 transition-colors overflow-hidden">
                  <template v-if="personalImageUrls.id_card_front">
                    <img :src="personalImageUrls.id_card_front" class="w-full h-full object-cover rounded" />
                  </template>
                  <template v-else>
                    <Upload class="w-6 h-6 text-gray-600 mb-1" />
                    <span class="text-sm text-gray-700">点击上传</span>
                  </template>
                  <input type="file" accept="image/*" class="hidden" @change="handleUpload('id_card_front', $event)" />
                </label>
              </div>
              <div>
                <label class="block text-sm font-medium text-gray-700 mb-1.5">身份证背面 <span class="text-red-500">*</span></label>
                <label class="flex flex-col items-center justify-center h-32 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-orange-500 transition-colors overflow-hidden">
                  <template v-if="personalImageUrls.id_card_back">
                    <img :src="personalImageUrls.id_card_back" class="w-full h-full object-cover rounded" />
                  </template>
                  <template v-else>
                    <Upload class="w-6 h-6 text-gray-600 mb-1" />
                    <span class="text-sm text-gray-700">点击上传</span>
                  </template>
                  <input type="file" accept="image/*" class="hidden" @change="handleUpload('id_card_back', $event)" />
                </label>
              </div>
            </div>
          </div>
        </template>

        <template v-if="verificationType === '2'">
          <h3 class="font-semibold mb-4 text-gray-900">企业认证信息</h3>
          <div class="space-y-4">
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-1.5">企业名称 <span class="text-red-500">*</span></label>
              <input
                v-model="enterpriseForm.company_name"
                type="text"
                class="w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 outline-none"
                placeholder="请输入企业名称"
