<script setup lang="ts">
import { ref, onMounted, onUnmounted, nextTick } from 'vue'
import { Send, User, Headphones, Clock } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

interface ChatMessage {
  id: number
  uid: number
  content: string
  is_admin: number
  admin_name: string
  created_at: string
}

const messages = ref<ChatMessage[]>([])
const inputContent = ref('')
const loading = ref(false)
const sending = ref(false)
const chatContainer = ref<HTMLElement>()
const userName = ref('')
let pollTimer: ReturnType<typeof setInterval> | null = null
let lastId = 0

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchUserInfo = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.info}`, {
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      userName.value = data.data.name || data.data.username || data.data.phone || ''
    }
  } catch {
    // ignore
  }
}

const scrollToBottom = async () => {
  await nextTick()
  if (chatContainer.value) {
    chatContainer.value.scrollTop = chatContainer.value.scrollHeight
  }
}

const fetchMessages = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.chat.list}`, {
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0) {
      messages.value = data.data || []
      if (messages.value.length > 0) {
        lastId = messages.value[messages.value.length - 1].id
      }
      scrollToBottom()
    }
  } catch (e) {
    console.error('[fetchMessages]', e)
  } finally {
    loading.value = false
  }
}

const pollMessages = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.chat.poll}?last_id=${lastId}`, {
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data && data.data.length > 0) {
      messages.value.push(...data.data)
      lastId = messages.value[messages.value.length - 1].id
      scrollToBottom()
    }
  } catch (e) {
    // ignore poll errors
  }
}

const startPolling = () => {
  stopPolling()
  pollTimer = setInterval(pollMessages, 5000)
}

const stopPolling = () => {
  if (pollTimer) {
    clearInterval(pollTimer)
    pollTimer = null
  }
}

const handleSend = async () => {
  const content = inputContent.value.trim()
  if (!content) return
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }
  sending.value = true
  try {
    const form = new FormData()
    form.append('content', content)
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.chat.send}`, {
      method: 'POST',
      headers: { 'uid': auth.uid, 'token': auth.token },
      body: form,
    })
    const data = await res.json()
    if (data.code === 0) {
      inputContent.value = ''
      fetchMessages()
    } else {
      toast.error(data.echo || '发送失败')
    }
  } catch (e) {
    console.error('[handleSend]', e)
    toast.error('发送失败')
  } finally {
    sending.value = false
  }
}

const handleKeydown = (e: KeyboardEvent) => {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault()
    handleSend()
  }
}

const formatTime = (t: string) => {
  if (!t) return '-'
  return t.replace('T', ' ').substring(0, 19)
}

onMounted(() => {
  fetchUserInfo()
  fetchMessages().then(() => {
    startPolling()
  })
})

onUnmounted(() => {
  stopPolling()
})
</script>

<template>
  <div class="flex flex-col h-[calc(100vh-64px)]">
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">在线客服</h1>
      <p class="text-gray-500 mt-1 text-sm">您好，请描述您遇到的问题，客服将尽快回复</p>
    </div>

    <div class="flex-1 overflow-y-auto p-6 bg-gray-50" ref="chatContainer">
      <div v-if="loading" class="text-center py-12 text-gray-400">加载中...</div>

      <div v-else-if="messages.length === 0" class="text-center py-12 text-gray-400">
        <p>暂无消息，输入您的问题开始对话</p>
      </div>

      <div v-else class="space-y-4 max-w-3xl mx-auto">
        <div v-for="msg in messages" :key="msg.id" :class="['flex gap-3', msg.is_admin === 0 ? 'justify-end' : 'justify-start']">
          <div v-if="msg.is_admin === 1" class="w-8 h-8 rounded-full bg-orange-100 text-orange-600 flex items-center justify-center flex-shrink-0">
            <Headphones class="w-4 h-4" />
          </div>
          <div :class="['max-w-[70%]', msg.is_admin === 0 ? 'order-1' : 'order-2']">
            <div class="text-xs mb-1" :class="msg.is_admin === 0 ? 'text-right text-blue-600' : 'text-left text-orange-600'">
              {{ msg.is_admin === 0 ? (userName || '我') : (msg.admin_name || '客服') }}
            </div>
            <div :class="['px-4 py-2.5 rounded-2xl text-sm leading-relaxed whitespace-pre-wrap', msg.is_admin === 0 ? 'bg-blue-500 text-white rounded-br-md' : 'bg-gray-100 text-gray-900 rounded-bl-md']">
              {{ msg.content }}
            </div>
            <div class="text-xs text-gray-400 mt-1 flex items-center gap-1" :class="msg.is_admin === 0 ? 'justify-end' : 'justify-start'">
              <Clock class="w-3 h-3" />
              {{ formatTime(msg.created_at) }}
            </div>
          </div>
          <div v-if="msg.is_admin === 0" class="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center flex-shrink-0 order-2">
            <User class="w-4 h-4" />
          </div>
        </div>
      </div>
    </div>

    <div class="bg-white border-t border-gray-200 px-6 py-4 shadow-[0_-2px_8px_rgba(0,0,0,0.05)]">
      <div class="max-w-3xl mx-auto flex items-end gap-3">
        <textarea
          v-model="inputContent"
          @keydown="handleKeydown"
          placeholder="输入您的问题..."
          rows="2"
          class="flex-1 border border-gray-300 rounded-xl px-4 py-2.5 text-sm resize-none focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        ></textarea>
        <button
          @click="handleSend"
          :disabled="sending || !inputContent.trim()"
          class="flex-shrink-0 w-10 h-10 rounded-full bg-blue-500 text-white flex items-center justify-center hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <Send class="w-4 h-4" />
        </button>
      </div>
    </div>
  </div>
</template>