<script setup lang="ts">
import { computed } from 'vue'
import { useRoute } from 'vue-router'

const route = useRoute()

const pageTitle = computed(() => {
  const path = route.path
  if (path.includes('/orders')) return '我的订单'
  if (path.includes('/billing')) return '账单管理'
  if (path.includes('/recharge-orders')) return '充值订单'
  if (path.includes('/balance-log')) return '余额流水'
  if (path.includes('/promotion')) return '推广'
  if (path.includes('/ticket')) return '工单管理'
  if (path.includes('/coupon')) return '优惠券'
  if (path.includes('/message')) return '站内消息'
  if (path.includes('/account')) return '账户中心'
  return '用户中心'
})

const pageDesc = computed(() => {
  const path = route.path
  if (path.includes('/orders')) return '查看和管理您的所有订单'
  if (path.includes('/billing')) return '查看您的消费账单'
  if (path.includes('/recharge-orders')) return '查看充值订单记录'
  if (path.includes('/balance-log')) return '查看余额变动明细'
  if (path.includes('/promotion')) return '推广返利管理'
  if (path.includes('/ticket')) return '提交和管理工单'
  if (path.includes('/coupon')) return '查看和使用优惠券'
  if (path.includes('/message')) return '查看站内消息'
  if (path.includes('/account')) return '管理您的账户信息'
  return ''
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">{{ pageTitle }}</h1>
      <p v-if="pageDesc" class="text-gray-500 mt-1">{{ pageDesc }}</p>
    </div>

    <div class="p-6">
      <div class="bg-white border border-gray-100 p-12 text-center">
        <div class="text-gray-400 text-6xl mb-4">🚧</div>
        <h3 class="text-lg font-medium text-gray-700 mb-2">功能开发中</h3>
        <p class="text-gray-500 text-sm">{{ pageTitle }}功能正在开发中，敬请期待</p>
      </div>
    </div>
  </div>
</template>
