<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { ChevronRight } from 'lucide-vue-next'

const router = useRouter()
const route = useRoute()

// 该组件同时用于控制台(/console/news)与官网公开页(/news)，
// 跳转详情时按当前所处路由选择对应的详情前缀，避免公开页跳到需登录的控制台路由。
const detailBase = computed(() =>
  route.path.startsWith('/console') ? '/console/news/detail/' : '/news/',
)

interface NewsItem {
  id: number
  title: string
  summary: string
  source: string
  author: string
  publish_time: string
}

const items = ref<NewsItem[]>([])
const page = ref(1)
const pageSize = 20
const loading = ref(false)
const finished = ref(false)
const errorMsg = ref('')

const load = async (reset = false) => {
  if (loading.value || (finished.value && !reset)) return
  loading.value = true
  errorMsg.value = ''
  const nextPage = reset ? 1 : page.value
  try {
    const res = await fetch(
      `${API_BASE_URL}${API_ENDPOINTS.news.list}?page=${nextPage}&page_size=${pageSize}`,
      { method: 'GET' },
    )
    const data = await res.json()
    if (data.code === 0 && data.data?.list) {
      const list = (data.data.list as Array<Record<string, unknown>>).map((n) => ({
        id: Number(n.id) || 0,
        title: (n.title as string) || '',
        summary: (n.summary as string) || '',
        source: (n.source as string) || '',
        author: (n.author as string) || '',
        publish_time: (n.publish_time as string) || '',
      }))
      items.value = reset ? list : [...items.value, ...list]
      page.value = nextPage + 1
      finished.value = list.length < pageSize
    } else {
      errorMsg.value = (data.echo as string) || '加载失败'
    }
  } catch {
    errorMsg.value = '网络错误，请稍后重试'
  } finally {
    loading.value = false
  }
}

const openDetail = (id: number) => router.push(`${detailBase.value}${id}`)

onMounted(() => load(true))
</script>

<template>
  <div class="p-6 space-y-6">
    <div class="flex items-center justify-between">
      <h1 class="text-2xl font-bold text-gray-900">新闻公告</h1>
    </div>

    <div class="section-card bg-white border border-gray-100 overflow-hidden">
      <div v-if="items.length === 0 && !loading" class="px-6 py-16 text-center text-gray-400">
        {{ errorMsg || '暂无公告' }}
      </div>
      <div v-else class="divide-y divide-gray-50">
        <div
          v-for="item in items"
          :key="item.id"
          class="px-6 py-4 hover:bg-gray-50 transition-colors cursor-pointer flex items-center justify-between gap-4"
          @click="openDetail(item.id)"
        >
          <div class="min-w-0">
            <p class="text-sm font-medium text-gray-900 truncate">{{ item.title }}</p>
            <p v-if="item.summary" class="text-xs text-gray-500 mt-1 truncate">{{ item.summary }}</p>
            <p class="text-xs text-gray-400 mt-1">
              <span v-if="item.source">{{ item.source }} · </span>
              <span v-if="item.author">{{ item.author }} · </span>
              {{ (item.publish_time || '').slice(0, 10) }}
            </p>
          </div>
          <ChevronRight class="w-4 h-4 text-gray-300 flex-shrink-0" />
        </div>
      </div>
    </div>

    <div v-if="loading" class="text-center text-sm text-gray-400 py-4">加载中…</div>
    <div v-else-if="!finished && items.length > 0" class="text-center">
      <button
        class="px-4 py-2 text-sm text-flame-500 hover:text-flame-600 font-medium"
        @click="load(false)"
      >
        加载更多
      </button>
    </div>
  </div>
</template>
