<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { Search, RefreshCw, CreditCard, ChevronLeft, ChevronRight, TrendingUp, TrendingDown, Wallet } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'

interface BalanceLog {
  id: number
  type: number
  amount: string
  balance_after: string
  description: string
  created_at: string
  order_no: string
}

const logs = ref<BalanceLog[]>([])
const loading = ref(false)
const searchKeyword = ref('')
const currentPage = ref(1)
const pageSize = ref(10)
const total = ref(0)
const currentBalance = ref('0.00')
const totalRecharge = ref('0.00')
const totalConsume = ref('0.00')

const typeMap: Record<number, { text: string; color: string; icon: any; isIncome: boolean }> = {
  1: { text: '充值', color: 'text-green-600', icon: TrendingUp, isIncome: true },
  2: { text: '消费', color: 'text-red-600', icon: TrendingDown, isIncome: false },
  3: { text: '退款', color: 'text-green-600', icon: TrendingUp, isIncome: true },
  4: { text: '系统调整', color: 'text-blue-600', icon: Wallet, isIncome: true },
}

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchLogs = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    const params = new URLSearchParams()
    params.set('page', String(currentPage.value))
    params.set('page_size', String(pageSize.value))
    if (searchKeyword.value) params.set('keyword', searchKeyword.value)
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.balanceLog}?${params.toString()}`, {
      method: 'GET',
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      logs.value = data.data.list || []
      total.value = data.data.total || 0
      currentBalance.value = data.data.current_balance || '0.00'
      totalRecharge.value = data.data.total_recharge || '0.00'
      totalConsume.value = data.data.total_consume || '0.00'
    } else {
      logs.value = []
      total.value = 0
    }
  } catch (e) {
    console.error('[fetchLogs] 异常', e)
    logs.value = []
    total.value = 0
  } finally {
    loading.value = false
  }
}

const handleSearch = () => {
  currentPage.value = 1
  fetchLogs()
}

const handleRefresh = () => {
  fetchLogs()
}

const prevPage = () => {
  if (currentPage.value > 1) {
    currentPage.value--
    fetchLogs()
  }
}

const nextPage = () => {
  const totalPages = Math.ceil(total.value / pageSize.value)
  if (currentPage.value < totalPages) {
    currentPage.value++
    fetchLogs()
  }
}

onMounted(() => {
  fetchLogs()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">余额流水</h1>
      <p class="text-gray-500 mt-1">查看您的余额变动明细</p>
    </div>

    <div class="p-6 space-y-4">
      <div class="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div class="bg-white border border-gray-100 p-5">
          <div class="flex items-center gap-3">
            <div class="w-12 h-12 bg-green-50 flex items-center justify-center">
              <Wallet class="w-6 h-6 text-green-500" />
            </div>
            <div>
              <p class="text-sm text-gray-500">当前余额</p>
              <p class="text-2xl font-bold text-gray-900">¥ {{ currentBalance }}</p>
            </div>
          </div>
        </div>
        <div class="bg-white border border-gray-100 p-5">
          <div class="flex items-center gap-3">
            <div class="w-12 h-12 bg-blue-50 flex items-center justify-center">
              <TrendingUp class="w-6 h-6 text-blue-500" />
            </div>
            <div>
              <p class="text-sm text-gray-500">累计充值</p>
              <p class="text-2xl font-bold text-green-600">¥ {{ totalRecharge }}</p>
            </div>
          </div>
        </div>
        <div class="bg-white border border-gray-100 p-5">
          <div class="flex items-center gap-3">
            <div class="w-12 h-12 bg-orange-50 flex items-center justify-center">
              <TrendingDown class="w-6 h-6 text-orange-500" />
            </div>
            <div>
              <p class="text-sm text-gray-500">累计消费</p>
              <p class="text-2xl font-bold text-red-600">¥ {{ totalConsume }}</p>
            </div>
          </div>
        </div>
      </div>

      <div class="bg-white border border-gray-100 p-4">
        <div class="flex items-center justify-between flex-wrap gap-4">
          <div class="flex items-center gap-3">
            <div class="relative">
              <Search class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
              <input
                v-model="searchKeyword"
                type="text"
                placeholder="搜索描述或订单号"
                class="pl-10 pr-4 py-2 border border-gray-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-colors w-64"
                @keyup.enter="handleSearch"
              />
            </div>
            <button @click="handleSearch" class="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 text-sm font-medium transition-colors">
              搜索
            </button>
          </div>
          <button @click="handleRefresh" class="flex items-center gap-2 px-3 py-2 border border-gray-300 text-gray-600 hover:bg-gray-50 transition-colors text-sm">
            <RefreshCw class="w-4 h-4" />
            刷新
          </button>
        </div>
      </div>

      <div class="bg-white border border-gray-200">
        <table class="w-full" v-if="!loading">
          <thead>
            <tr class="border-b border-gray-200 bg-gray-50">
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">流水号</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">类型</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">金额</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">变动后余额</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">描述</th>
              <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">时间</th>
            </tr>
          </thead>
          <tbody>
            <tr v-if="logs.length === 0">
              <td colspan="6" class="px-4 py-12 text-center text-gray-400">
                <CreditCard class="w-12 h-12 text-gray-300 mx-auto mb-2" />
                <p>暂无余额流水</p>
              </td>
            </tr>
            <tr v-for="log in logs" :key="log.id" class="border-b border-gray-100 hover:bg-gray-50 transition-colors">
              <td class="px-4 py-3">
                <div class="text-sm font-medium text-gray-900 font-mono">{{ log.order_no }}</div>
              </td>
              <td class="px-4 py-3">
                <span :class="['inline-flex items-center gap-1 text-sm font-medium', typeMap[log.type]?.color || 'text-gray-600']">
                  <component :is="typeMap[log.type]?.icon || Wallet" class="w-4 h-4" />
                  {{ typeMap[log.type]?.text || '未知' }}
                </span>
              </td>
              <td class="px-4 py-3">
                <span :class="['text-base font-bold', typeMap[log.type]?.isIncome ? 'text-green-600' : 'text-red-600']">
                  {{ typeMap[log.type]?.isIncome ? '+' : '-' }}¥{{ log.amount }}
                </span>
              </td>
              <td class="px-4 py-3">
                <span class="text-sm text-gray-700 font-medium">¥{{ log.balance_after }}</span>
              </td>
              <td class="px-4 py-3">
                <span class="text-sm text-gray-600">{{ log.description }}</span>
              </td>
              <td class="px-4 py-3 text-sm text-gray-500">{{ log.created_at }}</td>
            </tr>
          </tbody>
        </table>
        <div v-else class="px-4 py-12 text-center text-gray-400">加载中...</div>

        <div class="px-4 py-3 bg-gray-50 border-t border-gray-200 flex items-center justify-between">
          <div class="text-sm text-gray-500">
            共 <span class="font-medium text-gray-700">{{ total }}</span> 条记录
          </div>
          <div class="flex items-center gap-2">
            <button
              @click="prevPage"
              :disabled="currentPage <= 1"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft class="w-4 h-4" />
            </button>
            <span class="text-sm text-gray-600">
              第 <span class="font-medium">{{ currentPage }}</span> 页
            </span>
            <button
              @click="nextPage"
              :disabled="currentPage >= Math.ceil(total / pageSize)"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight class="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
