<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Send, Paperclip, Link as LinkIcon, Phone, Mail, Clock, XCircle, Headphones, User, Image, RotateCcw } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

interface TicketInfo {
  id: number
  uid: number
  description: string
  category: string
  other_category: string
  urgency: string
  status: number
  contact_phone: string
  ticket_type: string
  last_reply_at: string
  created_at: string
  updated_at: string
}

interface Reply {
  id: number
  ticket_id: number
  uid: number
  content: string
  is_admin: number
  created_at: string
  attachments?: Attachment[]
}

interface Attachment {
  id: number
  name: string
  url: string
  hash: string
}

interface TicketLink {
  id: number
  url: string
  text: string
}

interface Contact {
  id: number
  type: string
  value: string
  label: string
}

const route = useRoute()
const router = useRouter()

const ticket = ref<TicketInfo | null>(null)
const replies = ref<Reply[]>([])
const attachments = ref<Attachment[]>([])
const links = ref<TicketLink[]>([])
const contacts = ref<Contact[]>([])
const loading = ref(false)
const replyContent = ref('')
const submitting = ref(false)
const closing = ref(false)

const ticketId = computed(() => Number(route.params.id))

const statusMap: Record<number, { text: string; color: string; dot: string }> = {
  0: { text: '待回复', color: 'bg-yellow-100 text-yellow-700', dot: 'bg-yellow-500' },
  1: { text: '客户发送', color: 'bg-blue-100 text-blue-700', dot: 'bg-blue-500' },
  2: { text: '客服答复', color: 'bg-orange-100 text-orange-700', dot: 'bg-orange-500' },
  3: { text: '结案关闭', color: 'bg-gray-100 text-gray-500', dot: 'bg-gray-400' },
}

const urgencyMap: Record<string, string> = {
  fault: '产品故障',
  usage: '产品使用问题',
  consult: '产品咨询',
}

const categoryMap: Record<string, string> = {
  ecs: 'ECS',
  oss: '文件存储',
  rds: '云数据库MySQL',
  waf: 'WAF',
  vpc: 'VPC',
  ddos: 'DDoS高防防护',
  metal: '裸金属',
  elastic_ip: '弹性IP',
  auto_scale: '负载均衡',
  other: '其他',
  chat: '在线客服',
}

const ticketTypeMap: Record<string, { text: string; color: string }> = {
  standard: { text: '标准工单', color: 'bg-blue-50 text-blue-600' },
  chat: { text: '在线客服', color: 'bg-green-50 text-green-600' },
}

const isClosed = computed(() => ticket.value?.status === 3)
const canReply = computed(() => !isClosed.value && ticket.value !== null)

const isChatTicket = computed(() => ticket.value?.ticket_type === 'chat')

const replyUploading = ref(false)
const replyImages = ref<Array<{ name: string; url: string; hash: string }>>([])
const replyFileInput = ref<HTMLInputElement>()

let pollTimer: ReturnType<typeof setInterval> | null = null
let currentLastReplyAt = ''
const showConvertDialog = ref(false)
const convertCategory = ref('ecs')
const convertUrgency = ref('fault')
const converting = ref(false)

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchDetail = async () => {
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }
  loading.value = true
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.detail}?id=${ticketId.value}`, {
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      ticket.value = data.data.info || null
      replies.value = data.data.replies || []
      attachments.value = data.data.attachments || []
      links.value = data.data.links || []
      contacts.value = data.data.contacts || []
    } else {
      toast.error(data.echo || '工单不存在')
      router.push({ name: 'console-user-ticket-list' })
    }
  } catch (e) {
    console.error('[fetchDetail]', e)
    toast.error('加载失败')
  } finally {
    loading.value = false
  }
}

const handleSubmitReply = async () => {
  if (!replyContent.value.trim()) {
    toast.error('请输入回复内容')
    return
  }
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }
  submitting.value = true
  try {
    const form = new FormData()
    form.append('id', String(ticketId.value))
    form.append('content', replyContent.value.trim())
    if (replyImages.value.length > 0) {
      const attachments = replyImages.value.map(f => ({ name: f.name, url: f.url, hash: f.hash }))
      form.append('attachments', JSON.stringify(attachments))
    }
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.reply}`, {
      method: 'POST',
      headers: { 'uid': auth.uid, 'token': auth.token },
      body: form,
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('回复成功')
      replyContent.value = ''
      replyImages.value = []
      fetchDetail()
    } else {
      toast.error(data.echo || '回复失败')
    }
  } catch (e) {
    console.error('[handleSubmitReply]', e)
    toast.error('回复失败')
  } finally {
    submitting.value = false
  }
}

const handleReplyImageUpload = async (event: Event) => {
  const target = event.target as HTMLInputElement
  const files = target.files
  if (!files) return
  for (let i = 0; i < files.length; i++) {
    const file = files[i]
    if (file.size > 20 * 1024 * 1024) {
      toast.error('单个图片不得超过20M')
      continue
    }
    if (replyImages.value.length >= 5) {
      toast.error('最多上传5张图片')
      break
    }
    try {
      replyUploading.value = true
      const auth = getAuthHeaders()
      const tokenRes = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.avatar}/token`, {
        method: 'GET',
        headers: { 'uid': auth.uid, 'token': auth.token },
      })
      const tokenData = await tokenRes.json()
      if (tokenData.code !== 0) {
        toast.error(tokenData.echo || '获取上传地址失败')
        continue
      }
      const uploadUrl = tokenData.data.upload_url
      const formData = new FormData()
      formData.append('file', file)
      const uploadRes = await fetch(uploadUrl, { method: 'POST', body: formData })
      const uploadData = await uploadRes.json()
      if (uploadData.code !== 0) {
        toast.error(uploadData.echo || '上传失败')
        continue
      }
      const hash = uploadData.data?.hash || uploadData.data
      const urlRes = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.file.upload}`, {
        method: 'POST',
        headers: { 'uid': auth.uid, 'token': auth.token, 'Content-Type': 'application/x-www-form-urlencoded' },
        body: `hash=${encodeURIComponent(hash)}`,
      })
      const urlData = await urlRes.json()
      const realUrl = urlData.data?.url || ''
      replyImages.value.push({ name: file.name, url: realUrl, hash: hash })
    } catch (e) {
      console.error('[replyImageUpload] 异常', e)
      toast.error('图片上传失败')
    } finally {
      replyUploading.value = false
    }
  }
  if (target) target.value = ''
}

const removeReplyImage = (index: number) => {
  replyImages.value.splice(index, 1)
}

const handleClose = async () => {
  if (!confirm('确定要关闭此工单吗？关闭后将无法继续回复。')) return
  const auth = getAuthHeaders()
  if (!auth) return
  closing.value = true
  try {
    const form = new FormData()
    form.append('id', String(ticketId.value))
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.close}`, {
      method: 'POST',
      headers: { 'uid': auth.uid, 'token': auth.token },
      body: form,
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('工单已关闭')
      fetchDetail()
    } else {
      toast.error(data.echo || '操作失败')
    }
  } catch (e) {
    console.error('[handleClose]', e)
    toast.error('操作失败')
  } finally {
    closing.value = false
  }
}

const startPolling = () => {
  stopPolling()
  pollTimer = setInterval(async () => {
    const auth = getAuthHeaders()
    if (!auth) return
    try {
      const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.poll}?id=${ticketId.value}&last_reply_at=${encodeURIComponent(currentLastReplyAt)}`, {
        headers: { 'uid': auth.uid, 'token': auth.token },
      })
      const data = await res.json()
      if (data.code === 0 && data.has_new) {
        currentLastReplyAt = data.last_reply_at || ''
        fetchDetail()
      }
    } catch (e) {
      // ignore poll errors
    }
  }, 5000)
}

const stopPolling = () => {
  if (pollTimer) {
    clearInterval(pollTimer)
    pollTimer = null
  }
}

const handleConvert = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  converting.value = true
  try {
    const form = new FormData()
    form.append('id', String(ticketId.value))
    form.append('category', convertCategory.value)
    form.append('urgency', convertUrgency.value)
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.convert}`, {
      method: 'POST',
      headers: { 'uid': auth.uid, 'token': auth.token },
      body: form,
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('工单转换成功')
      showConvertDialog.value = false
      fetchDetail()
    } else {
      toast.error(data.echo || '转换失败')
    }
  } catch (e) {
    console.error('[handleConvert]', e)
    toast.error('转换失败')
  } finally {
    converting.value = false
  }
}

const formatTime = (t: string) => {
  if (!t) return '-'
  return t.replace('T', ' ').substring(0, 19)
}

const isImage = (name: string) => /\.(jpg|jpeg|gif|png|bmp|webp)$/i.test(name)

onMounted(() => {
  if (!ticketId.value || isNaN(ticketId.value)) {
    router.push({ name: 'console-user-ticket-list' })
    return
  }
  fetchDetail().then(() => {
    currentLastReplyAt = ticket.value?.last_reply_at || ''
    startPolling()
  })
})

onUnmounted(() => {
  stopPolling()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <div class="flex items-center gap-4">
        <button @click="router.push({ name: 'console-user-ticket-list' })" class="text-gray-400 hover:text-gray-600">
          <ArrowLeft class="w-5 h-5" />
        </button>
        <div class="flex-1">
          <div class="flex items-center gap-3">
            <h1 class="text-2xl font-bold text-gray-900">工单 #{{ ticketId }}</h1>
            <span v-if="ticket" :class="['inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium', ticketTypeMap[ticket.ticket_type]?.color || 'bg-gray-50 text-gray-600']">
              {{ ticketTypeMap[ticket.ticket_type]?.text || '标准工单' }}
            </span>
            <span v-if="ticket" :class="['inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium', statusMap[ticket.status]?.color]">
              <span :class="['w-1.5 h-1.5 rounded-full', statusMap[ticket.status]?.dot]"></span>
              {{ statusMap[ticket.status]?.text || '未知' }}
            </span>
          </div>
          <p class="text-gray-500 mt-1 text-sm" v-if="ticket">{{ formatTime(ticket.created_at) }}</p>
        </div>
      </div>
    </div>

    <div class="p-6 max-w-4xl mx-auto">
      <div v-if="loading" class="text-center py-12 text-gray-400">加载中...</div>

      <template v-else-if="ticket">
        <!-- 工单主帖 -->
        <div class="bg-white border border-gray-200 rounded-lg overflow-hidden mb-4">
          <div class="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
            <div class="flex items-center gap-3">
              <div class="w-10 h-10 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-semibold">
                <User class="w-5 h-5" />
              </div>
              <div>
                <div class="font-medium text-gray-900">我</div>
                <div class="text-xs text-gray-400 flex items-center gap-1">
                  <Clock class="w-3 h-3" />
                  {{ formatTime(ticket.created_at) }}
                </div>
              </div>
            </div>
            <div class="text-right">
              <div class="text-xs text-gray-400">紧急性</div>
              <div :class="['text-sm font-medium', ticket.urgency === 'fault' ? 'text-red-600' : ticket.urgency === 'usage' ? 'text-orange-600' : 'text-gray-600']">
                {{ urgencyMap[ticket.urgency] || ticket.urgency }}
              </div>
            </div>
          </div>
          <div class="px-6 py-4">
            <div class="flex items-center gap-2 mb-3">
              <span class="inline-flex items-center px-2 py-0.5 rounded-full text-xs bg-blue-50 text-blue-600">
                {{ categoryMap[ticket.category] || ticket.category }}
              </span>
              <span v-if="ticket.other_category" class="text-xs text-gray-500">{{ ticket.other_category }}</span>
            </div>
            <div class="text-gray-700 leading-relaxed whitespace-pre-wrap">{{ ticket.description }}</div>

            <div v-if="ticket.contact_phone" class="mt-4 pt-4 border-t border-gray-50 flex items-center gap-2 text-sm text-gray-500">
              <Phone class="w-4 h-4 text-gray-400" />
              <span class="font-mono">{{ ticket.contact_phone }}</span>
            </div>
          </div>

          <!-- 附件 / 链接 / 联系方式 -->
          <div v-if="attachments.length > 0 || links.length > 0 || contacts.length > 0" class="px-6 py-3 border-t border-gray-50 bg-gray-50/50 space-y-3">
            <div v-if="attachments.length > 0" class="flex items-start gap-2 text-sm">
              <span class="text-gray-400 w-16 flex-shrink-0 flex items-center gap-1"><Paperclip class="w-3.5 h-3.5" />附件</span>
              <div class="flex flex-wrap gap-2">
                <div v-for="att in attachments" :key="att.id" class="relative">
                  <a v-if="isImage(att.name)" :href="att.url" target="_blank" class="block w-16 h-16 border border-gray-200 rounded overflow-hidden">
                    <img :src="att.url" class="w-full h-full object-cover" />
                  </a>
                  <a v-else :href="att.url" target="_blank" class="inline-flex items-center gap-1 px-2 py-1 bg-white border border-gray-200 rounded text-xs text-blue-600 hover:bg-blue-50">
                    <Paperclip class="w-3.5 h-3.5" />
                    {{ att.name }}
                  </a>
                </div>
              </div>
            </div>
            <div v-if="links.length > 0" class="flex items-start gap-2 text-sm">
              <span class="text-gray-400 w-16 flex-shrink-0 flex items-center gap-1"><LinkIcon class="w-3.5 h-3.5" />链接</span>
              <div class="flex flex-wrap gap-2">
                <a v-for="link in links" :key="link.id" :href="link.url" target="_blank" class="inline-flex items-center gap-1 px-2 py-1 bg-white border border-gray-200 rounded text-xs text-blue-600 hover:bg-blue-50">
                  <LinkIcon class="w-3.5 h-3.5" />
                  {{ link.text }}
                </a>
              </div>
            </div>
            <div v-if="contacts.length > 0" class="flex items-start gap-2 text-sm">
              <span class="text-gray-400 w-16 flex-shrink-0 flex items-center gap-1"><Phone class="w-3.5 h-3.5" />其他联系</span>
              <div class="flex flex-wrap gap-2">
                <span v-for="ct in contacts" :key="ct.id" class="inline-flex items-center px-2 py-1 bg-white border border-gray-200 rounded text-xs text-gray-600">
                  <component :is="ct.type === 'phone' ? Phone : Mail" class="w-3.5 h-3.5 mr-1 text-gray-400" />
                  {{ ct.label }}
                </span>
              </div>
            </div>
          </div>
        </div>

        <!-- 回复盖楼 -->
        <div v-for="reply in replies" :key="reply.id" :class="['bg-white border rounded-lg overflow-hidden mb-3 border-l-4', reply.is_admin === 1 ? 'border-l-orange-400' : 'border-l-blue-400']">
          <div class="px-6 py-3 border-b border-gray-50 flex items-center justify-between">
            <div class="flex items-center gap-3">
              <div :class="['w-8 h-8 rounded-full flex items-center justify-center font-semibold text-sm', reply.is_admin === 1 ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600']">
                <component :is="reply.is_admin === 1 ? Headphones : User" class="w-4 h-4" />
              </div>
              <div>
                <div class="font-medium text-sm text-gray-900 flex items-center gap-1">
                  {{ reply.is_admin === 1 ? '客服' : '我' }}
                  <span v-if="reply.is_admin === 1" class="inline-flex items-center px-1.5 py-0.5 rounded text-xs bg-orange-50 text-orange-600">官方</span>
                </div>
                <div class="text-xs text-gray-400 flex items-center gap-1">
                  <Clock class="w-3 h-3" />
                  {{ formatTime(reply.created_at) }}
                </div>
              </div>
            </div>
          </div>
          <div class="px-6 py-4">
            <div class="text-gray-700 leading-relaxed whitespace-pre-wrap">{{ reply.content }}</div>
            <div v-if="reply.attachments && reply.attachments.length > 0" class="mt-3 flex flex-wrap gap-2">
              <div v-for="att in reply.attachments" :key="att.id" class="inline-block">
                <a
                  :href="att.url"
                  target="_blank"
                  v-if="/\.(jpg|jpeg|gif|png|bmp|webp)$/i.test(att.name)"
                  class="block w-16 h-16 border border-gray-200 rounded overflow-hidden"
                >
                  <img :src="att.url" class="w-full h-full object-cover" />
                </a>
                <a
                  :href="att.url"
                  target="_blank"
                  v-else
                  class="inline-flex items-center gap-1 px-2 py-1 bg-white border border-gray-200 rounded text-xs text-blue-600 hover:bg-blue-50"
                >
                  <Paperclip class="w-3 h-3" />
                  {{ att.name }}
                </a>
              </div>
            </div>
          </div>
        </div>

        <!-- 回复表单 -->
        <div v-if="canReply" class="bg-white border border-gray-200 rounded-lg overflow-hidden">
          <div class="px-6 py-3 border-b border-gray-100">
            <div class="font-medium text-sm text-gray-700">追加回复</div>
            <p class="text-xs text-gray-400 mt-0.5">回复后工单状态将变为"客户发送"，等待客服处理</p>
          </div>
          <div class="p-6">
            <textarea
              v-model="replyContent"
              rows="4"
              placeholder="请输入回复内容..."
              class="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none text-sm resize-none"
            ></textarea>
            <div class="mt-2 flex items-center gap-2">
              <input
                ref="replyFileInput"
                type="file"
                accept="image/*"
                multiple
                class="hidden"
                @change="handleReplyImageUpload"
              />
              <button
                type="button"
                @click="replyFileInput?.click()"
                class="flex items-center gap-1 px-3 py-1.5 text-xs text-gray-500 border border-gray-200 hover:bg-gray-50 rounded-lg transition-colors"
              >
                <Image class="w-3.5 h-3.5" />
                上传图片
              </button>
              <span v-if="replyUploading" class="text-xs text-gray-400">上传中...</span>
            </div>
            <div v-if="replyImages.length > 0" class="mt-2 flex flex-wrap gap-2">
              <div v-for="(img, idx) in replyImages" :key="idx" class="relative inline-block">
                <img :src="img.url" class="w-16 h-16 object-cover border border-gray-200 rounded" />
                <button
                  @click="removeReplyImage(idx)"
                  class="absolute -top-1.5 -right-1.5 w-4 h-4 bg-red-500 text-white rounded-full text-xs flex items-center justify-center"
                >x</button>
              </div>
            </div>
            <div class="mt-3 flex items-center justify-between">
              <button
                @click="handleClose"
                :disabled="closing"
                class="flex items-center gap-1.5 px-4 py-2 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 rounded-lg transition-colors disabled:opacity-50"
              >
                <XCircle class="w-4 h-4" />
                关闭工单
              </button>
              <div class="flex items-center gap-2">
                <button
                  v-if="isChatTicket"
                  @click="showConvertDialog = true"
                  class="flex items-center gap-1.5 px-4 py-2 text-sm text-green-600 border border-green-300 hover:bg-green-50 rounded-lg transition-colors"
                >
                  <RotateCcw class="w-4 h-4" />
                  转为标准工单
                </button>
                <button
                  @click="handleSubmitReply"
                  :disabled="submitting || !replyContent.trim()"
                  class="flex items-center gap-1.5 px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <Send class="w-4 h-4" />
                  发送回复
                </button>
              </div>
            </div>
          </div>
        </div>

        <!-- 已关闭提示 -->
        <div v-else class="bg-gray-100 border border-gray-200 rounded-lg p-8 text-center">
          <XCircle class="w-12 h-12 text-gray-300 mx-auto mb-2" />
          <p class="text-gray-500 text-sm">该工单已结案关闭</p>
          <button @click="router.push({ name: 'console-user-ticket-submit' })" class="mt-4 text-sm text-blue-600 hover:text-blue-700">
            提交新工单
          </button>
        </div>

        <!-- 转换工单弹窗 -->
        <div v-if="showConvertDialog" class="fixed inset-0 z-50 bg-black/50 flex items-center justify-center">
          <div class="bg-white rounded-xl shadow-xl w-full max-w-md mx-4 p-6">
            <h3 class="text-lg font-semibold mb-4">聊天工单转标准工单</h3>
            <p class="text-sm text-gray-500 mb-4">转换后工单类型将变为标准工单，请选择分类和紧急性</p>
            <div class="space-y-3">
              <div>
                <label class="block text-sm text-gray-600 mb-1">问题分类</label>
                <select v-model="convertCategory" class="w-full px-3 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none text-sm">
                  <option value="ecs">ECS</option>
                  <option value="oss">文件存储</option>
                  <option value="rds">云数据库MySQL</option>
