<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { Search, RefreshCw, ChevronDown, ChevronUp, ChevronLeft, ChevronRight, Server } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'

interface PromoVm {
  id: number
  customer: string
  server_name: string
  server_ip: string
  os: string
  region: string
  config: string
  expire_time: string
  status: number
}

const vms = ref<PromoVm[]>([])
const loading = ref(false)
const showFilters = ref(false)
const searchField = ref('uid')
const searchKeyword = ref('')

const currentPage = ref(1)
const pageSize = ref(20)
const total = ref(0)

const statusMap: Record<number, { text: string; color: string }> = {
  0: { text: '已停止', color: 'bg-gray-100 text-gray-500' },
  1: { text: '运行中', color: 'bg-green-100 text-green-700' },
  2: { text: '已过期', color: 'bg-red-100 text-red-700' },
  3: { text: '重启中', color: 'bg-yellow-100 text-yellow-700' },
}

const searchFields = [
  { value: 'uid', label: '用户UID' },
  { value: 'server_name', label: '服务器名称' },
  { value: 'server_ip', label: '服务器IP' },
]

const mockVms: PromoVm[] = [
  {
    id: 1, customer: '用户A', server_name: 'web-server-01', server_ip: '192.168.1.100',
    os: 'CentOS 7.9', region: '华东1-杭州', config: '2核4G 40G SSD',
    expire_time: '2025-07-24 23:59:59', status: 1,
  },
  {
    id: 2, customer: '用户B', server_name: 'db-server-01', server_ip: '192.168.1.101',
    os: 'Ubuntu 22.04', region: '华东1-杭州', config: '4核8G 100G SSD',
    expire_time: '2025-07-23 23:59:59', status: 1,
  },
  {
    id: 3, customer: '用户A', server_name: 'test-server-01', server_ip: '192.168.1.102',
    os: 'Windows Server 2019', region: '华北1-北京', config: '2核4G 40G SSD',
    expire_time: '2024-08-22 23:59:59', status: 0,
  },
  {
    id: 4, customer: '用户D', server_name: 'app-server-01', server_ip: '192.168.1.103',
    os: 'CentOS 8', region: '华南1-广州', config: '8核16G 200G SSD',
    expire_time: '2024-07-17 23:59:59', status: 2,
  },
  {
    id: 5, customer: '用户E', server_name: 'prod-server-01', server_ip: '192.168.1.104',
    os: 'Ubuntu 20.04', region: '华东1-杭州', config: '16核32G 500G SSD',
    expire_time: '2025-07-20 23:59:59', status: 1,
  },
]

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchVms = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    vms.value = mockVms
    total.value = mockVms.length
  } catch (e) {
    console.error('[fetchVms] 异常', e)
  } finally {
    loading.value = false
  }
}

const handleSearch = () => {
  currentPage.value = 1
  fetchVms()
}

const handleRefresh = () => {
  fetchVms()
}

const prevPage = () => {
  if (currentPage.value > 1) {
    currentPage.value--
    fetchVms()
  }
}

const nextPage = () => {
  const totalPages = Math.ceil(total.value / pageSize.value)
  if (currentPage.value < totalPages) {
    currentPage.value++
    fetchVms()
  }
}

onMounted(() => {
  fetchVms()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">推广云主机</h1>
      <p class="text-gray-500 mt-1">查看推广用户的云主机列表</p>
    </div>

    <div class="p-6">
      <div class="bg-white border border-gray-100">
        <div class="p-4 border-b border-gray-100">
          <div class="flex items-center gap-2 flex-wrap">
            <div class="relative">
              <select
                v-model="searchField"
                class="pl-3 pr-8 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none appearance-none cursor-pointer min-w-[120px]"
              >
                <option v-for="f in searchFields" :key="f.value" :value="f.value">{{ f.label }}</option>
              </select>
              <svg class="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="6 9 12 15 18 9"></polyline>
              </svg>
            </div>

            <div class="relative">
              <input
                v-model="searchKeyword"
                type="text"
                placeholder="请输入"
                class="pl-3 pr-10 py-1.5 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none w-48"
                @keyup.enter="handleSearch"
              />
              <button
                @click="handleSearch"
                class="absolute right-2 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-500"
              >
                <Search class="w-4 h-4" />
              </button>
            </div>

            <button
              @click="showFilters = !showFilters"
              class="flex items-center gap-1 px-3 py-1.5 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 transition-colors"
            >
              {{ showFilters ? '收起' : '展开' }}
              <ChevronDown v-if="!showFilters" class="w-4 h-4" />
              <ChevronUp v-else class="w-4 h-4" />
            </button>

            <button
              @click="handleRefresh"
              class="flex items-center gap-2 px-3 py-1.5 text-sm text-gray-600 border border-gray-300 hover:bg-gray-50 transition-colors"
            >
              <RefreshCw class="w-4 h-4" />
            </button>
          </div>

          <div v-if="showFilters" class="mt-4 pt-4 border-t border-gray-100 grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label class="block text-sm text-gray-600 mb-1">服务器状态</label>
              <select class="w-full px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">
                <option value="">全部状态</option>
                <option value="1">运行中</option>
                <option value="0">已停止</option>
                <option value="2">已过期</option>
                <option value="3">重启中</option>
              </select>
            </div>
            <div>
              <label class="block text-sm text-gray-600 mb-1">地域</label>
              <select class="w-full px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">
                <option value="">全部地域</option>
                <option value="hangzhou">华东1-杭州</option>
                <option value="beijing">华北1-北京</option>
                <option value="guangzhou">华南1-广州</option>
              </select>
            </div>
            <div>
              <label class="block text-sm text-gray-600 mb-1">操作系统</label>
              <select class="w-full px-3 py-2 border border-gray-300 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none">
                <option value="">全部系统</option>
                <option value="centos">CentOS</option>
                <option value="ubuntu">Ubuntu</option>
                <option value="windows">Windows</option>
              </select>
            </div>
          </div>
        </div>

        <div class="overflow-x-auto">
          <table class="w-full min-w-max">
            <thead>
              <tr class="border-b border-gray-200 bg-gray-50">
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">客户</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">服务器名称</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">服务器IP</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">系统</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">地域</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">配置</th>
                <th class="px-4 py-3 text-left text-xs font-medium text-gray-500 whitespace-nowrap">到期时间</th>
                <th class="px-4 py-3 text-center text-xs font-medium text-gray-500 whitespace-nowrap">状态</th>
              </tr>
            </thead>
            <tbody>
              <tr v-if="loading" class="border-b border-gray-100">
                <td colspan="8" class="px-4 py-12 text-center text-gray-400">
                  <RefreshCw class="w-6 h-6 animate-spin mx-auto mb-2" />
                  加载中...
                </td>
              </tr>
              <tr v-else-if="vms.length === 0" class="border-b border-gray-100">
                <td colspan="8" class="px-4 py-12 text-center text-gray-400">
                  <Server class="w-12 h-12 text-gray-300 mx-auto mb-2" />
                  <p>无数据</p>
                </td>
              </tr>
              <tr
                v-for="vm in vms"
                :key="vm.id"
                class="border-b border-gray-100 hover:bg-gray-50 transition-colors"
              >
                <td class="px-4 py-3 text-sm text-gray-700 whitespace-nowrap">{{ vm.customer }}</td>
                <td class="px-4 py-3 text-sm text-gray-700 whitespace-nowrap">{{ vm.server_name }}</td>
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap font-mono">{{ vm.server_ip }}</td>
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">{{ vm.os }}</td>
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">{{ vm.region }}</td>
                <td class="px-4 py-3 text-sm text-gray-600 whitespace-nowrap">{{ vm.config }}</td>
                <td class="px-4 py-3 text-sm text-gray-500 whitespace-nowrap">{{ vm.expire_time }}</td>
                <td class="px-4 py-3 text-center">
                  <span :class="['inline-flex items-center px-2 py-0.5 text-xs font-medium', statusMap[vm.status]?.color || 'bg-gray-100 text-gray-500']">
                    {{ statusMap[vm.status]?.text || '未知' }}
                  </span>
                </td>
              </tr>
            </tbody>
          </table>
        </div>

        <div class="px-4 py-4 border-t border-gray-100 flex items-center justify-between">
          <div class="text-sm text-gray-500">
            共 <span class="font-medium text-gray-700">{{ total }}</span> 条
          </div>
          <div class="flex items-center gap-2">
            <select
              v-model="pageSize"
              class="px-2 py-1 border border-gray-300 text-sm"
            >
              <option :value="10">10条/页</option>
              <option :value="20">20条/页</option>
              <option :value="50">50条/页</option>
              <option :value="100">100条/页</option>
            </select>

            <button
              @click="prevPage"
              :disabled="currentPage <= 1"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft class="w-4 h-4" />
            </button>

            <span class="text-sm text-gray-600">
              第 <span class="font-medium">{{ currentPage }}</span> 页
            </span>

            <button
              @click="nextPage"
              :disabled="currentPage >= Math.ceil(total / pageSize)"
              class="p-1.5 border border-gray-300 text-gray-600 hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight class="w-4 h-4" />
            </button>

            <span class="text-sm text-gray-500 ml-2">前往</span>
            <input
              v-model.number="currentPage"
              type="number"
              min="1"
              class="w-12 px-2 py-1 border border-gray-300 text-sm text-center"
            />
            <span class="text-sm text-gray-500">页</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
