<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { Upload, Link, Phone, Plus, Send, AlertCircle } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

const router = useRouter()

const urgency = ref('usage')
const description = ref('')
const problemCategory = ref('')
const otherCategory = ref('')
const contactPhone = ref('')
const submitted = ref(false)
const showContactModal = ref(false)
const showLinkModal = ref(false)

const linkUrl = ref('')
const linkText = ref('')
const links = ref<Array<{ url: string; text: string }>>([])

const extraPhone = ref('')
const contactTimeMode = ref<'anytime' | 'scheduled'>('anytime')
const contactTimeStart = ref('')
const contactTimeEnd = ref('')
const extraEmails = ref('')

const extraContactList = ref<Array<{ type: string; value: string; label: string }>>([])

const urgencyOptions = [
  { value: 'fault', label: '产品故障' },
  { value: 'usage', label: '产品使用问题' },
  { value: 'consult', label: '产品咨询' },
]

const productCategories = [
  { value: 'ecs', label: 'ECS' },
  { value: 'metal', label: '裸金属' },
  { value: 'elastic_ip', label: '弹性IP' },
  { value: 'auto_scale', label: '负载均衡' },
  { value: 'rds', label: '云数据库MySQL' },
  { value: 'oss', label: '文件存储' },
  { value: 'waf', label: 'WAF' },
  { value: 'vpc', label: 'VPC' },
  { value: 'ddos', label: 'DDoS高防防护' },
]

const uploadedFiles = ref<Array<{ name: string; url: string; hash: string }>>([])
const maxDescriptionLength = 1024
const uploading = ref(false)

const descriptionLength = computed(() => description.value.length)

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const handleFileUpload = async (event: Event) => {
  const target = event.target as HTMLInputElement
  const files = target.files
  if (!files) return
  for (let i = 0; i < files.length; i++) {
    const file = files[i]
    if (file.size > 20 * 1024 * 1024) {
      toast.error('单个附件不得超过20M')
      continue
    }
    if (uploadedFiles.value.length >= 5) {
      toast.error('最多上传5个附件')
      continue
    }
    try {
      uploading.value = true
      const auth = getAuthHeaders()
      if (!auth) {
        toast.error('请先登录')
        return
      }
      const tokenRes = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.avatar}/token`, {
        method: 'GET',
        headers: { 'uid': auth.uid, 'token': auth.token },
      })
      const tokenData = await tokenRes.json()
      if (tokenData.code !== 0) {
        toast.error(tokenData.echo || '获取上传地址失败')
        continue
      }
      const uploadUrl = tokenData.data.upload_url
      const formData = new FormData()
      formData.append('file', file)
      const uploadRes = await fetch(uploadUrl, {
        method: 'POST',
        body: formData,
      })
      const uploadData = await uploadRes.json()
      if (uploadData.code !== 0) {
        toast.error(uploadData.echo || '文件上传失败')
        continue
      }
      const hash = uploadData.data?.hash || uploadData.data
      const hashStr = typeof hash === 'string' ? hash : String(hash)
      // 远程仅回传 hash，需调用后端 /v1/user/file/upload 用 hash 换取实际可访问的 URL
      const urlRes = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.file.upload}`, {
        method: 'POST',
        headers: {
          'uid': auth.uid,
          'token': auth.token,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: `hash=${encodeURIComponent(hashStr)}`,
      })
      const urlData = await urlRes.json()
      if (urlData.code !== 0) {
        toast.error(urlData.echo || '获取文件地址失败')
        continue
      }
      const realUrl = urlData.data?.url || ''
      uploadedFiles.value.push({
        name: file.name,
        url: realUrl,
        hash: hashStr,
      })
    } catch (e) {
      console.error('[fileUpload] 异常', e)
      toast.error('文件上传失败')
    } finally {
      uploading.value = false
      if (target) target.value = ''
    }
  }
}

const removeFile = (index: number) => {
  uploadedFiles.value.splice(index, 1)
}

const handleSubmit = async () => {
  if (!description.value.trim()) {
    toast.error('请输入问题描述')
    return
  }
  if (!urgency.value) {
    toast.error('请选择问题紧急性')
    return
  }
  if (!problemCategory.value && !otherCategory.value) {
    toast.error('请选择或输入问题分类')
    return
  }
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }
  submitted.value = true
  try {
    const form = new FormData()
    form.append('description', description.value.trim())
    if (contactPhone.value) form.append('contact_phone', contactPhone.value)

    form.append('urgency', urgency.value)
    form.append('category', problemCategory.value || 'other')
    form.append('other_category', otherCategory.value.trim())
    if (uploadedFiles.value.length > 0) {
      form.append('attachments', JSON.stringify(uploadedFiles.value))
    }
    if (links.value.length > 0) {
      form.append('links', JSON.stringify(links.value))
    }
    if (extraContactList.value.length > 0) {
      form.append('contacts', JSON.stringify(extraContactList.value))
    }
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ticket.submit}`, {
      method: 'POST',
      headers: { 'uid': auth.uid, 'token': auth.token },
      body: form,
    })
    const data = await res.json()
    if (data.code === 0) {
      toast.success('工单提交成功，我们将尽快处理')
      const ticketId = data.data?.id
      if (ticketId) {
        router.push({ name: 'console-user-ticket-detail', params: { id: ticketId } })
      } else {
        router.push({ name: 'console-user-ticket-list' })
      }
    } else {
      toast.error(data.echo || '工单提交失败')
      submitted.value = false
    }
  } catch (e) {
    console.error('[handleSubmit]', e)
    toast.error('工单提交失败')
    submitted.value = false
  }
}

const resetForm = () => {
  urgency.value = 'usage'
  description.value = ''
  problemCategory.value = ''
  otherCategory.value = ''
  uploadedFiles.value = []
  submitted.value = false
  extraContactList.value = []
}

const fetchUserInfo = async () => {
  try {
    const auth = getAuthHeaders()
    if (!auth) {
      toast.error('请先登录')
      return
    }
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.info}`, {
      method: 'GET',
      headers: {
        'uid': auth.uid,
        'token': auth.token,
      },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      contactPhone.value = data.data.phone || ''
    }
  } catch (e) {
    console.error('[fetchUserInfo] 异常', e)
  }
}

onMounted(() => {
  fetchUserInfo()
})

const openContactModal = () => {
  extraPhone.value = ''
  contactTimeMode.value = 'anytime'
  contactTimeStart.value = ''
  contactTimeEnd.value = ''
  extraEmails.value = ''
  showContactModal.value = true
}

const closeContactModal = () => {
  showContactModal.value = false
}

const confirmContactModal = () => {
  if (extraPhone.value.trim()) {
    extraContactList.value.push({
      type: 'phone',
      value: extraPhone.value.trim(),
      label: `手机(${extraPhone.value.trim()})${contactTimeMode.value === 'scheduled' && contactTimeStart.value && contactTimeEnd.value ? ` ${contactTimeStart.value}-${contactTimeEnd.value}` : ''}`,
    })
  }
  if (extraEmails.value.trim()) {
    const emails = extraEmails.value.trim().split(/\s+/).slice(0, 2).filter(Boolean)
    emails.forEach((email) => {
      extraContactList.value.push({
        type: 'email',
        value: email,
        label: `邮箱(${email})`,
      })
    })
  }
  toast.success('联系方式已添加')
  closeContactModal()
}

const removeExtraContact = (index: number) => {
  extraContactList.value.splice(index, 1)
}

const openLinkModal = () => {
  linkUrl.value = ''
  linkText.value = ''
  showLinkModal.value = true
}

const closeLinkModal = () => {
  showLinkModal.value = false
}

const confirmLinkModal = () => {
  if (!linkUrl.value.trim()) {
    toast.error('请输入链接地址')
    return
  }
  if (!linkText.value.trim()) {
    toast.error('请输入链接文本')
    return
  }
  links.value.push({
    url: linkUrl.value.trim(),
    text: linkText.value.trim(),
  })
  closeLinkModal()
}

const removeLink = (index: number) => {
  links.value.splice(index, 1)
}
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">提交工单</h1>
      <p class="text-gray-500 mt-1">提交您的问题，我们将尽快为您处理</p>
    </div>

    <div class="p-6">
      <div class="bg-white border border-gray-100 p-6">
        <form @submit.prevent="handleSubmit" class="space-y-6">
          <div>
            <label class="block text-sm font-medium text-gray-700 mb-3">
              <span class="text-red-500">*</span> 问题紧急性
            </label>
            <div class="flex flex-wrap gap-6">
              <label
                v-for="option in urgencyOptions"
                :key="option.value"
                class="flex items-center gap-2 cursor-pointer"
              >
                <input
                  type="radio"
                  :value="option.value"
                  v-model="urgency"
                  class="w-4 h-4 text-blue-600 focus:ring-blue-500"
                />
                <span class="text-sm text-gray-700">{{ option.label }}</span>
              </label>
            </div>
          </div>

          <div>
            <label class="block text-sm font-medium text-gray-700 mb-2">
              <span class="text-red-500">*</span> 问题描述
            </label>
            <div class="relative border border-gray-300 focus-within:border-blue-500 focus-within:ring-1 focus-within:ring-blue-500 transition-colors">
              <div v-if="links.length > 0" class="flex flex-wrap gap-2 p-3 pb-2 border-b border-gray-200">
                <div
                  v-for="(link, index) in links"
                  :key="index"
                  class="inline-flex items-center gap-1 px-2 py-0.5 bg-blue-50 text-blue-600 text-sm"
                >
                  <Link class="w-3.5 h-3.5" />
                  <a :href="link.url" target="_blank" class="hover:underline">{{ link.text }}</a>
                  <button type="button" @click="removeLink(index)" class="ml-1 hover:text-red-500">
                    ×
                  </button>
                </div>
              </div>
              <textarea
                v-model="description"
                rows="5"
                :maxlength="maxDescriptionLength"
                placeholder="请输入问题描述"
                class="w-full px-4 py-3 outline-none resize-none"
              ></textarea>
              <div class="absolute bottom-2 right-3 text-xs text-gray-400">
                {{ descriptionLength }}/{{ maxDescriptionLength }}
              </div>
            </div>
          </div>

          <div>
            <button type="button" @click="openLinkModal" class="flex items-center gap-2 text-sm text-blue-600 hover:text-blue-700">
              <Link class="w-4 h-4" />
              添加链接
            </button>
          </div>

          <div>
            <label class="block text-sm font-medium text-gray-700 mb-2">上传附件</label>
            <div class="flex flex-wrap gap-3">
              <div
                v-for="(file, index) in uploadedFiles"
                :key="index"
                class="relative w-20 h-20 border border-gray-200 rounded overflow-hidden bg-gray-50"
              >
                <img v-if="/\.(jpg|jpeg|gif|png|bmp|webp)$/i.test(file.name)" :src="file.url" class="w-full h-full object-cover" />
                <div v-else class="w-full h-full flex flex-col items-center justify-center text-xs text-gray-500 px-1">
                  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="w-6 h-6 text-gray-400 mb-1 flex-shrink-0"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
                  <span class="truncate w-full text-center">{{ file.name }}</span>
                </div>
                <button
                  type="button"
                  @click="removeFile(index)"
                  class="absolute top-1 right-1 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center text-xs hover:bg-red-600"
                >
                  ×
                </button>
              </div>
              <label
                v-if="uploadedFiles.length < 5"
                class="w-20 h-20 border-2 border-dashed border-gray-300 rounded flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50/30 transition-colors"
                :class="{ 'opacity-50 pointer-events-none': uploading }"
              >
                <Upload v-if="!uploading" class="w-6 h-6 text-gray-400" />
                <svg v-else xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-6 h-6 text-blue-500 animate-spin"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>
                <span class="text-xs text-gray-500 mt-1">{{ uploading ? '上传中' : '上传附件' }}</span>
                <input type="file" multiple class="hidden" @change="handleFileUpload" :disabled="uploading" />
              </label>
            </div>
            <p class="text-xs text-gray-500 mt-2">
              支持扩展名：.rar.zip.7z.doc.docx.xls.pdf.jpg.jpeg.gif.png.mp4等格式，单个附件不得超过20M，最多上传5个附件
            </p>
          </div>

          <div>
            <label class="block text-sm font-medium text-gray-700 mb-3">
              <span class="text-red-500">*</span> 问题分类
            </label>
            <div class="flex flex-wrap gap-4 mb-3">
              <label
                v-for="cat in productCategories"
                :key="cat.value"
                class="flex items-center gap-2 cursor-pointer"
              >
                <input
                  type="radio"
                  :value="cat.value"
                  v-model="problemCategory"
                  class="w-4 h-4 text-blue-600 focus:ring-blue-500"
                />
                <span class="text-sm text-gray-700">{{ cat.label }}</span>
              </label>
            </div>
            <div class="flex items-center gap-3">
              <input
                v-model="otherCategory"
                type="text"
                placeholder="请输入其他问题分类"
                class="flex-1 px-4 py-2 border border-gray-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-colors text-sm"
              />
              <button type="button" class="px-4 py-2 text-sm text-blue-600 border border-blue-500 hover:bg-blue-50 transition-colors">
                全部产品
              </button>
            </div>
          </div>

          <div>
            <label class="block text-sm font-medium text-gray-700 mb-2">联系方式</label>
            <div class="space-y-2">
              <div class="flex items-center gap-3">
                <div class="relative flex-1">
                  <Phone class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                  <input
                    :value="`手机(${contactPhone};)`"
                    type="text"
                    disabled
                    class="w-full pl-10 pr-4 py-2 border border-gray-200 bg-gray-50 text-gray-500 text-sm"
                  />
                </div>
                <button type="button" @click="openContactModal" class="flex items-center gap-1 text-sm text-blue-600 hover:text-blue-700">
                  <Plus class="w-4 h-4" />
                  添加其他联系方式
                </button>
              </div>
              <div
                v-for="(item, index) in extraContactList"
                :key="index"
                class="flex items-center gap-3"
              >
                <div class="relative flex-1">
                  <Phone v-if="item.type === 'phone'" class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                  <svg v-else xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400"><rect width="20" height="16" x="2" y="4" rx="2"/><path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7"/></svg>
                  <input
                    :value="item.label"
                    type="text"
                    disabled
                    class="w-full pl-10 pr-4 py-2 border border-gray-200 bg-gray-50 text-gray-500 text-sm"
                  />
                </div>
                <button
                  type="button"
                  @click="removeExtraContact(index)"
                  class="text-sm text-red-500 hover:text-red-600"
                >
                  移除
                </button>
              </div>
            </div>
          </div>

          <div class="pt-4 border-t border-gray-100">
            <button
              type="submit"
              :disabled="submitted"
              class="bg-blue-600 hover:bg-blue-700 text-white px-8 py-2.5 font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
              <Send class="w-4 h-4" />
              提交
            </button>
          </div>
        </form>
      </div>
    </div>
    <Teleport to="body">
      <div v-if="showLinkModal" class="fixed inset-0 z-50 flex items-center justify-center">
        <div class="absolute inset-0 bg-black/40" @click="closeLinkModal"></div>
        <div class="relative bg-white shadow-2xl w-full max-w-lg mx-4">
          <div class="flex items-center justify-between px-6 py-4 border-b border-gray-100">
            <h3 class="text-base font-semibold text-gray-900">添加链接</h3>
            <button @click="closeLinkModal" class="text-gray-400 hover:text-gray-600">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-5 h-5"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
            </button>
          </div>
          <div class="p-6 space-y-5">
            <div class="flex items-center">
              <label class="block text-sm font-medium text-gray-700 w-24 flex-shrink-0">链接</label>
              <input
                v-model="linkUrl"
                type="text"
                placeholder="https://某个链接"
                class="flex-1 px-4 py-2 border border-gray-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-colors text-sm"
              />
            </div>
            <div class="flex items-center">
              <label class="block text-sm font-medium text-gray-700 w-24 flex-shrink-0">要显示的文本</label>
              <input
                v-model="linkText"
                type="text"
                placeholder="链接文本"
                class="flex-1 px-4 py-2 border border-gray-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-colors text-sm"
              />
            </div>
          </div>
          <div class="px-6 py-4 border-t border-gray-100 flex justify-end gap-3">
            <button @click="closeLinkModal" class="px-6 py-2 text-sm font-medium text-gray-700 border border-gray-300 hover:bg-gray-50 transition-colors">取消</button>
            <button @click="confirmLinkModal" class="px-6 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 transition-colors">确定</button>
          </div>
        </div>
      </div>

      <div v-if="showContactModal" class="fixed inset-0 z-50 flex items-center justify-center">
        <div class="absolute inset-0 bg-black/40" @click="closeContactModal"></div>
        <div class="relative bg-white shadow-2xl w-full max-w-[640px] mx-4">
          <div class="flex items-center justify-between px-6 py-4 border-b border-gray-100">
            <h3 class="text-base font-semibold text-gray-900">新增联系方式</h3>
            <button @click="closeContactModal" class="text-gray-400 hover:text-gray-600">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="w-5 h-5"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
            </button>
          </div>
          <div class="p-6 space-y-5">
            <div>
              <p class="text-sm text-gray-700 mb-2">默认将给以下用户发送消息通知:</p>
              <div class="px-4 py-2 bg-amber-50 text-sm text-gray-800">
                {{ contactPhone || '未获取到手机号' }}
              </div>
            </div>
            <div>
              <p class="text-sm text-gray-700 mb-3">需要新增联系方式，请在下方新增：</p>
            </div>
            <div>
              <label class="block text-sm font-medium text-gray-700 mb-2 w-24 flex-shrink-0">联系手机</label>
              <input
                v-model="extraPhone"
                type="text"
                placeholder="请输入其他联系手机"
                class="w-full px-4 py-2 border border-gray-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-colors text-sm"
              />
            </div>
            <div class="flex items-start">
              <label class="block text-sm font-medium text-gray-700 mb-2 w-24 flex-shrink-0 pt-1">联系时间</label>
              <div class="flex-1">
                <div class="flex items-center gap-6 mb-3">
                  <label class="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      value="anytime"
                      v-model="contactTimeMode"
                      class="w-4 h-4 text-blue-600 focus:ring-blue-500"
                    />
                    <span class="text-sm text-blue-600">任意时间</span>
                  </label>
                  <label class="flex items-center gap-2 cursor-pointer">
                    <input
                      type="radio"
                      value="scheduled"
                      v-model="contactTimeMode"
                      class="w-4 h-4 text-blue-600 focus:ring-blue-500"
                    />
                    <span class="text-sm text-gray-700">指定时间</span>
                  </label>
                </div>
                <div v-if="contactTimeMode === 'scheduled'" class="flex items-center gap-3 text-sm">
                  <input
                    v-model="contactTimeStart"
                    type="time"
                    class="px-3 py-1.5 border border-gray-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-colors"
                  />
                  <span class="text-gray-500">至</span>
                  <input
                    v-model="contactTimeEnd"
                    type="time"
                    class="px-3 py-1.5 border border-gray-300 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition-colors"
                  />
                </div>
              </div>
            </div>
            <div class="flex items-start">
              <label class="block text-sm font-medium text-gray-700 mb-2 w-24 flex-shrink-0 pt-1">邮箱</label>
              <input
                v-model="extraEmails"
                type="text"
