<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { Copy, Check, Megaphone, AlertCircle } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

const promotionLink = ref('')
const copied = ref(false)
const loading = ref(false)

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchPromotionLink = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  loading.value = true
  try {
    const affCode = auth.uid
    promotionLink.value = `${window.location.origin}/promotion?aff=${affCode}`
  } catch (e) {
    console.error('[fetchPromotionLink] 异常', e)
  } finally {
    loading.value = false
  }
}

const copyLink = async () => {
  if (!promotionLink.value) return
  try {
    await navigator.clipboard.writeText(promotionLink.value)
    copied.value = true
    toast.success('链接已复制到剪贴板')
    setTimeout(() => {
      copied.value = false
    }, 2000)
  } catch (e) {
    const input = document.createElement('input')
    input.value = promotionLink.value
    document.body.appendChild(input)
    input.select()
    document.execCommand('copy')
    document.body.removeChild(input)
    copied.value = true
    toast.success('链接已复制到剪贴板')
    setTimeout(() => {
      copied.value = false
    }, 2000)
  }
}

onMounted(() => {
  fetchPromotionLink()
})
</script>

<template>
  <div>
    <div class="bg-white border-b border-gray-100 px-6 py-5">
      <h1 class="text-2xl font-bold text-gray-900">推广链接</h1>
      <p class="text-gray-500 mt-1">获取您的专属推广链接</p>
    </div>

    <div class="p-6">
      <div class="bg-white border border-gray-100 p-6">
        <div class="bg-green-50 border border-green-200 px-4 py-3 mb-4 flex items-center gap-3">
          <Megaphone class="w-5 h-5 text-green-600 flex-shrink-0" />
          <span class="text-sm text-green-700 font-medium">我的推广链接</span>
        </div>

        <div class="flex items-center gap-3">
          <div class="flex-1 relative">
            <input
              :value="promotionLink"
              type="text"
              readonly
              class="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 text-sm text-gray-700 cursor-text font-mono"
            />
          </div>
          <button
            @click="copyLink"
            :disabled="!promotionLink || copied"
            class="flex items-center gap-2 px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Check v-if="copied" class="w-4 h-4" />
            <Copy v-else class="w-4 h-4" />
            {{ copied ? '已复制' : '复制链接' }}
          </button>
        </div>

        <p class="text-sm text-gray-500 mt-3 pl-1">
          （复制链接，发送给用户，客户注册后将成为您的客户）
        </p>
      </div>
    </div>
  </div>
</template>