<script setup lang="ts">
import { ref, onMounted, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Wallet, CreditCard, AlertCircle } from 'lucide-vue-next'
import { API_BASE_URL, API_ENDPOINTS } from '@/config/api'
import { toast } from '@/composables/useToast'

const route = useRoute()
const router = useRouter()

const payMethods = [
  { key: 'balance', name: '余额支付', icon: Wallet },
  { key: 'alipay', name: '支付宝', icon: CreditCard },
  { key: 'wechat', name: '微信支付', icon: CreditCard },
]

const orderId = ref<string>('')
const orderNo = ref<string>('')
const amount = ref<string>('0.00')
const currentBalance = ref<string>('0.00')
const orderStatus = ref<number>(0)
const orderRemark = ref<string>('')
const instanceInfo = ref<any>(null)

const loading = ref(false)
const selectedPayMethod = ref<string>('balance')

const getAuthHeaders = () => {
  const uid = localStorage.getItem('uid')
  const token = localStorage.getItem('token')
  if (!uid || !token) return null
  return { uid, token }
}

const fetchBalance = async () => {
  const auth = getAuthHeaders()
  if (!auth) return
  try {
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.user.balance}`, {
      method: 'GET',
      headers: { 'uid': auth.uid, 'token': auth.token },
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      currentBalance.value = data.data.balance || '0.00'
    }
  } catch (e) {
    console.error('[fetchBalance] 异常', e)
  }
}

const fetchOrderDetail = async () => {
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }
  const id = route.query.id as string
  if (!id) {
    toast.error('订单不存在')
    router.push('/console/ecs')
    return
  }
  orderId.value = id

  try {
    const body = new URLSearchParams()
    body.set('id', orderId.value)
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ecs.order.detail}`, {
      method: 'POST',
      headers: {
        'uid': auth.uid,
        'token': auth.token,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: body.toString(),
    })
    const data = await res.json()
    if (data.code === 0 && data.data) {
      orderNo.value = data.data.order_no
      amount.value = data.data.amount
      orderStatus.value = data.data.status
      orderRemark.value = data.data.remark || ''
      if (data.data.instance_info) {
        instanceInfo.value = data.data.instance_info
      }
    } else {
      toast.error(data.echo || '获取订单详情失败')
    }
  } catch (e) {
    console.error('[fetchOrderDetail] 异常', e)
    toast.error('获取订单详情失败')
  }
}

const handlePay = async () => {
  const auth = getAuthHeaders()
  if (!auth) {
    toast.error('请先登录')
    return
  }

  loading.value = true
  try {
    const body = new URLSearchParams()
    body.set('order_id', orderId.value)
    body.set('pay_method', selectedPayMethod.value)
    const res = await fetch(`${API_BASE_URL}${API_ENDPOINTS.ecs.order.pay}`, {
      method: 'POST',
      headers: {
        'uid': auth.uid,
        'token': auth.token,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: body.toString(),
    })
    const data = await res.json()
    if (data.code === 0) {
      if (selectedPayMethod.value === 'balance') {
        toast.success('支付成功，实例已创建')
        router.push('/console/ecs')
      } else {
        if (data.data.pay_url) {
          window.location.href = data.data.pay_url
        } else {
          toast.success('订单已创建，请前往支付')
        }
      }
    } else {
      toast.error(data.echo || '支付失败')
    }
  } catch (e) {
    console.error('[handlePay] 异常', e)
    toast.error('支付失败')
  } finally {
    loading.value = false
  }
}

const goBack = () => {
  router.push('/console/ecs')
}

const isBalanceEnough = computed(() => {
  return parseFloat(currentBalance.value) >= parseFloat(amount.value)
})

const statusText = computed(() => {
  const statusMap: Record<number, string> = {
    0: '待支付',
    1: '已支付',
    2: '已取消',
  }
  return statusMap[orderStatus.value] || '未知'
})

const statusColor = computed(() => {
  const colorMap: Record<number, string> = {
    0: 'bg-yellow-100 text-yellow-700',
    1: 'bg-green-100 text-green-700',
    2: 'bg-gray-100 text-gray-500',
  }
  return colorMap[orderStatus.value] || 'bg-gray-100 text-gray-500'
})

onMounted(() => {
  fetchBalance()
  fetchOrderDetail()
})
</script>

<template>
  <div class="p-6 h-full overflow-y-auto">
    <div class="flex items-center gap-4 mb-6">
      <button @click="goBack" class="flex items-center gap-1 text-gray-500 hover:text-gray-700 transition-colors">
        <ArrowLeft class="w-5 h-5" />
        <span>返回实例列表</span>
      </button>
      <h1 class="text-xl font-bold text-gray-900">订单支付</h1>
    </div>

    <div v-if="orderStatus === 1" class="mb-6 bg-green-50 border border-green-200 px-6 py-4 flex items-center gap-3">
      <span class="text-green-600 font-medium">订单已支付完成</span>
      <button @click="router.push('/console/ecs')" class="ml-auto text-sm text-green-600 underline">查看实例列表</button>
    </div>

    <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <div class="lg:col-span-2 space-y-6">
        <div class="bg-white border border-gray-100 p-6">
          <h2 class="text-lg font-semibold text-gray-900 mb-4">订单信息</h2>
          <div class="space-y-3 text-sm">
            <div class="flex justify-between">
              <span class="text-gray-600">订单号</span>
              <span class="font-mono text-gray-900">{{ orderNo }}</span>
            </div>
            <div class="flex justify-between">
              <span class="text-gray-600">订单状态</span>
              <span :class="['px-2 py-1 rounded text-xs font-medium', statusColor]">{{ statusText }}</span>
            </div>
            <div class="flex justify-between">
              <span class="text-gray-600">商品名称</span>
              <span class="text-gray-900">云服务器ECS实例</span>
            </div>
            <div v-if="instanceInfo" class="flex justify-between">
              <span class="text-gray-600">配置</span>
              <span class="text-gray-900">{{ instanceInfo.spec }}</span>
            </div>
            <div v-if="orderRemark" class="flex justify-between">
              <span class="text-gray-600">备注</span>
              <span class="text-gray-900">{{ orderRemark }}</span>
            </div>
            <div class="flex justify-between pt-3 border-t border-gray-100">
              <span class="text-gray-600 font-medium">实付金额</span>
              <span class="text-xl font-bold text-red-500">¥ {{ amount }}</span>
            </div>
          </div>
        </div>

        <div v-if="orderStatus === 0" class="bg-white border border-gray-100 p-6">
          <h2 class="text-lg font-semibold text-gray-900 mb-4">选择支付方式</h2>
          <div class="space-y-3">
            <div
              v-for="method in payMethods"
              :key="method.key"
              @click="selectedPayMethod = method.key"
              :class="[
                'relative flex items-center gap-3 px-6 py-4 border-2 cursor-pointer transition-all',
                selectedPayMethod === method.key
                  ? 'border-blue-500 bg-blue-50/50'
                  : 'border-gray-200 hover:border-gray-300'
              ]"
            >
              <div class="flex items-center gap-2">
                <component :is="method.icon" class="w-6 h-6 text-gray-600" />
                <span class="text-sm font-medium text-gray-700">{{ method.name }}</span>
              </div>
              <div
                v-if="selectedPayMethod === method.key"
                class="absolute -bottom-0.5 -right-0.5 w-0 h-0 border-l-[16px] border-l-transparent border-b-[16px] border-b-blue-500"
              >
                <svg class="absolute bottom-[-14px] right-[-2px] w-3 h-3 text-white" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/>
                </svg>
              </div>
            </div>
          </div>

          <div v-if="selectedPayMethod === 'balance'" class="mt-4 p-4 bg-gray-50 border border-gray-200">
            <div class="flex items-center gap-2">
              <Wallet class="w-4 h-4 text-gray-500" />
              <span class="text-sm text-gray-600">当前账户余额</span>
              <span :class="[
                'text-sm font-bold ml-auto',
                isBalanceEnough ? 'text-green-600' : 'text-red-600'
              ]">¥ {{ currentBalance }}</span>
            </div>
            <div v-if="!isBalanceEnough" class="mt-2 flex items-center gap-2 text-sm text-red-600">
              <AlertCircle class="w-4 h-4" />
              <span>余额不足，请选择其他支付方式或先充值</span>
            </div>
          </div>
        </div>
      </div>

      <div class="lg:col-span-1">
        <div class="bg-white border border-gray-100 sticky top-6">
          <div class="px-6 py-4 border-b border-gray-100">
            <h3 class="font-medium text-gray-900">订单结算</h3>
          </div>
          <div class="p-6 space-y-4">
            <div class="flex items-center justify-between text-sm">
              <span class="text-gray-600">商品金额</span>
              <span class="text-gray-900">¥ {{ amount }}</span>
            </div>
            <div class="flex items-center justify-between text-sm">
              <span class="text-gray-600">优惠</span>
              <span class="text-gray-900">- ¥0.00</span>
            </div>
            <div class="border-t border-gray-100 pt-4 flex items-center justify-between">
              <span class="text-base font-medium text-gray-900">实付金额</span>
              <span class="text-xl font-bold text-red-500">¥ {{ amount }}</span>
            </div>
            <button
              v-if="orderStatus === 0"
              @click="handlePay"
              :disabled="loading || (selectedPayMethod === 'balance' && !isBalanceEnough)"
              class="w-full py-3 bg-flame-500 text-white text-sm font-medium hover:bg-flame-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {{ loading ? '支付中...' : '立即支付' }}
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>